      // If not found, try parsing quantity and finding base item
      const quantityMatch = itemName.match(/(.+?)\s*\((\d+)\s*(?:feet?|lbs?|gp|sp|cp|gold|silver|copper)?\)/i);
      if (quantityMatch) {
