// Helper to convert plural class names in link text to singular valid class names



const normalizeClassName = (text) => {



  const trimmed = text.trim();



  if (CLASS_ICON_MAP[trimmed]) return trimmed;



  if (trimmed.endsWith('es')) {



    const singular = trimmed.slice(0, -2);



    if (CLASS_ICON_MAP[singular]) return singular;



  }



  if (trimmed.endsWith('s')) {



    const singular = trimmed.slice(0, -1);



    if (CLASS_ICON_MAP[singular]) return singular;



  }



  return null;



};







// Helper to process markdown content inside blocks (paragraphs, lists, etc.)
const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

// Only allow safe schemes for external links (blocks javascript:, data:, etc.)
const isSafeUrl = (url) => /^(https?:|mailto:|#|\/)/i.test(String(url || '').trim());

const processMarkdownContent = (text) => {
  if (!text) return text;

  // Split into paragraphs by double newlines
  const paragraphs = text.split('\n\n');
  const processedParagraphs = paragraphs.map(pText => {
    let p = pText.trim();
    if (!p) return '';

    // Handle list lines
    if (p.startsWith('- ') || p.startsWith('• ')) {
      // Split by newline and process each list item
      const items = p.split('\n').map(item => {
        let cleanItem = item.replace(/^[\u2022\-]\s*/, '').trim();
        // Process bold, italic, links inside list item
        cleanItem = cleanItem.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
        cleanItem = cleanItem.replace(/\*(.*?)\*/g, '<em>$1</em>');
        cleanItem = cleanItem.replace(/\[(.*?)\]\((.*?)\)/g, (match, linkText, url) => {
          const safeText = escapeHtml(linkText);
          if (url.includes('/') && !/^[a-z]+:/i.test(url)) {
            const [cat, sub] = url.split('/');
            return `<a href="#${escapeHtml(sub)}" class="rules-link" data-category="${escapeHtml(cat)}" data-subcategory="${escapeHtml(sub)}">${safeText}</a>`;
          }
          if (!isSafeUrl(url)) {
            return safeText;
          }
          return `<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer" class="rules-external-link">${safeText}</a>`;
        });
        return `<li>${cleanItem}</li>`;
      }).join('');
      return `<ul>${items}</ul>`;
    }

    // Check if this paragraph is a standalone header (starts and ends with ** and no other ** inside)
    const isStandaloneHeader = p.startsWith('**') && p.endsWith('**') && !p.slice(2, -2).includes('**');

    // Process bold, italic, and links
    p = p.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    p = p.replace(/\*(.*?)\*/g, '<em>$1</em>');
    p = p.replace(/\[(.*?)\]\((.*?)\)/g, (match, linkText, url) => {
      const safeText = escapeHtml(linkText);
      if (url.includes('/') && !/^[a-z]+:/i.test(url)) {
        const [cat, sub] = url.split('/');
        return `<a href="#${escapeHtml(sub)}" class="rules-link" data-category="${escapeHtml(cat)}" data-subcategory="${escapeHtml(sub)}">${safeText}</a>`;
      }
      if (!isSafeUrl(url)) {
        return safeText;
      }
      return `<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer" class="rules-external-link">${safeText}</a>`;
    });

    // Replace single newlines with <br>
    p = p.replace(/\n/g, '<br>');

    if (isStandaloneHeader) {
      return `<p class="rules-standalone-header">${p}</p>`;
    }
    return `<p>${p}</p>`;
  });

  return processedParagraphs.filter(p => p !== '').join('');
};

// Simple markdown processor for basic formatting with internal link support
const processMarkdown = (text) => {
  if (!text) return text;

  // Normalize line endings first
  let processed = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

  // Split lines and group into blockquote and standard text blocks
  const lines = processed.split('\n');
  const blocks = [];
  let currentBlock = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const isQuote = line.startsWith('>');

    if (currentBlock === null) {
      currentBlock = {
        type: isQuote ? 'blockquote' : 'text',
        lines: [isQuote ? line.replace(/^>\s?/, '') : line]
      };
    } else if (currentBlock.type === 'blockquote' && isQuote) {
      currentBlock.lines.push(line.replace(/^>\s?/, ''));
    } else if (currentBlock.type === 'text' && !isQuote) {
      currentBlock.lines.push(line);
    } else {
      blocks.push(currentBlock);
      currentBlock = {
        type: isQuote ? 'blockquote' : 'text',
        lines: [isQuote ? line.replace(/^>\s?/, '') : line]
      };
    }
  }
  if (currentBlock !== null) {
    blocks.push(currentBlock);
  }

  // Process each block individually
  const processedBlocks = blocks.map(block => {
    const content = block.lines.join('\n');
    if (block.type === 'blockquote') {
      return `<blockquote>${processMarkdownContent(content)}</blockquote>`;
    } else {
      return processMarkdownContent(content);
    }
  });

  let result = processedBlocks.join('');

  // Auto-link all recognised LORE_DICTIONARY terms after all markdown is processed
  result = autoLinkTerminology(result);

  return result;
};







// High-performance parser that converts static HTML strings with embedded <LoreLink> or <a> tags into active React components



const InteractiveRulesContent = ({ contentHtml, handleClassClick, handleSubcategoryClick }) => {



  const parsedElements = useMemo(() => {



    if (!contentHtml) return null;







    try {



      const parser = new DOMParser();



      // Wrap contentHtml in a wrapper div to ensure it parses as a single DOM fragment



      const doc = parser.parseFromString(`<div>${contentHtml}</div>`, 'text/html');



      const rootDiv = doc.body.firstChild;







      const renderDomNode = (node, keyVal) => {



        if (node.nodeType === 3) { // Node.TEXT_NODE



          return node.nodeValue;



        }







        if (node.nodeType === 1) { // Node.ELEMENT_NODE



          const tagName = node.tagName.toLowerCase();







          // Check if it's our custom LoreLink tag



          if (tagName === 'lorelink') {



            const termId = node.getAttribute('termid');



            const children = Array.from(node.childNodes).map((child, index) =>



              renderDomNode(child, `lore-child-${index}`)



            );



            return (



              <LoreLink key={keyVal} termId={termId}>



                {children}



              </LoreLink>



            );



          }







          // Check if it's our custom internal rules-link



          if (tagName === 'a' && node.className.includes('rules-link')) {



            const cat = node.getAttribute('data-category');



            const sub = node.getAttribute('data-subcategory');



            const children = Array.from(node.childNodes).map((child, index) =>



              renderDomNode(child, `link-child-${index}`)



            );



            return (



              <span



                key={keyVal}



                className="rules-link clickable-link"



                style={{ cursor: 'pointer', color: '#d4af37', fontWeight: '600' }}



                onClick={(e) => {



                  e.preventDefault();



                  e.stopPropagation();



                  if (sub === 'classes') {



                    const className = normalizeClassName(node.textContent);



                    if (className) {



                      handleClassClick(className);



                    } else {



                      handleSubcategoryClick(cat, sub);



                    }



                  } else {



                    handleSubcategoryClick(cat, sub);



                  }



                }}



              >



                {children}



              </span>



            );



          }







          // For standard HTML tags, map them to React elements



          const attribs = {};



          for (const attr of node.attributes) {



            let name = attr.name;



            if (name === 'class') name = 'className';



            // convert style string to react style object if present



            if (name === 'style') {



              const styleObj = {};



              attr.value.split(';').forEach(style => {



                const parts = style.split(':');



                if (parts.length >= 2) {



                  const k = parts[0].trim();



                  const v = parts.slice(1).join(':').trim();



                  const camelKey = k.replace(/-./g, x => x[1].toUpperCase());



                  styleObj[camelKey] = v;



                }



              });



              attribs.style = styleObj;



              continue;



            }



            attribs[name] = attr.value;



          }



          attribs.key = keyVal;







          const children = Array.from(node.childNodes).map((child, index) =>



            renderDomNode(child, `${tagName}-child-${index}`)



          );







          return React.createElement(tagName, attribs, ...children);



        }







        return null;



      };







      // Return the children of our root wrapper div



      return Array.from(rootDiv.childNodes).map((child, index) =>



        renderDomNode(child, `root-${index}`)



      );



    } catch (error) {



      console.error("DOMParser rendering error:", error);



      // Fallback in case of parse failures



      return <div dangerouslySetInnerHTML={{ __html: sanitizeHtml(contentHtml) }} />;



    }



  }, [contentHtml, handleClassClick, handleSubcategoryClick]);







  if (!contentHtml) return null;







  return <div className="rules-content-interactive">{parsedElements}</div>;



};







