                  key={cellIdx}



                  className={isClickable ? 'clickable-cell' : ''}



                  onClick={isClickable ? () => handleClassClick(cell) : undefined}



                  style={isClickable ? { cursor: 'pointer', color: '#d4af37', fontWeight: '600' } : {}}



                >



                  {isSpellObject ? (



                    <>



                      {cell.prefix && <span style={{ marginRight: '4px', whiteSpace: 'nowrap' }}>{cell.prefix}</span>}



                      <SpellIconTooltip spellId={cell.spellId} />



                    </>



                  ) : (



                    <>



                      {isSkillAbilitiesTable && cellIdx === 0 && typeof cell === 'string' ? (



                        <>



                          <SkillAbilityIconTooltip skillName={cell} />



                          <span>{cell}</span>



                        </>



                      ) : (



                        <>



                          {icon && (



                            <FontAwesomeIcon icon={icon} className="class-cell-icon" aria-hidden="true" />



                          )}



                          {cell}



                        </>



                      )}



                    </>



                  )}



                </td>



              );



            })}



          </tr>



        ))}



      </tbody>



    </table>



  );







  const changeTablePage = (nextPage) => {



    const clamped = Math.min(Math.max(nextPage, 0), maxPageIndex);



    onPageChange(clamped);



  };







  const themeColor = getThemeColor(sectionTheme);



  // has-two-pages enables the book-spine ::before pseudo-element only when genuinely split



  const wrapperClass = `rules-table-wrapper ${!hasRightPage ? 'single-page' : 'has-two-pages'}`;







  return (



    <div className="rules-table-container rules-table-themed" key={table.title} style={{ '--table-theme-color': themeColor }}>



      {table.title && <h5 className="rules-table-title">{table.title}</h5>}



      {table.description && <p className="rules-table-description">{table.description}</p>}



      <div className={wrapperClass}>



        {/* Left Page */}



        <div className="rules-table-page-left">



          {renderTablePage(leftPageRows, startIdx)}



        </div>







        {/* Right Page */}



        {hasRightPage && (



          <div className="rules-table-page-right">



            {renderTablePage(rightPageRows, startIdx + rowsPerSide)}



          </div>



        )}



      </div>







      {/* Page Navigation */}



      {totalPages > 1 && (



        <div className="rules-table-pagination">



          <button



            className="rules-table-page-button"



            onClick={() => changeTablePage(tablePage - 1)}



            disabled={tablePage === 0}



            aria-label="Previous page"



          >



            <i className="fas fa-chevron-left"></i>



          </button>



          <span className="rules-table-page-indicator">



            Page {tablePage + 1} / {totalPages}



          </span>



          <button



            className="rules-table-page-button"



            onClick={() => changeTablePage(tablePage + 1)}



            disabled={tablePage >= totalPages - 1}



            aria-label="Next page"



          >



            <i className="fas fa-chevron-right"></i>



          </button>



        </div>



      )}



    </div>



  );



});







const GET_THEME_COLOR = (theme) => {



  const colors = {



    mechanic: '#8a1a10',



    combat: '#9c281a',



    narrative: '#6d4021',



    danger: '#a62424',



    nature: '#2a5c2d',



    arcane: '#5b2c80',



    undead: '#3d1c47',



    trade: '#997400',



    social: '#b25900'



  };



  return colors[theme] || '#6d4021';



};








const CODEX_CATEGORY_ALIASES = {
  travel: 'travel-exploration',
  exploration: 'travel-exploration',
  'travel-exploration': 'travel-exploration',
  lore: 'world-lore',
  'world-lore': 'world-lore',
  bestiary: 'world-lore',
  lexicon: 'world-lore',
  combat: 'combat-system',
  'combat-system': 'combat-system',
  magic: 'magic-system',
  'magic-system': 'magic-system',
  spells: 'magic-system',
  character: 'character-creation',
  'character-creation': 'character-creation',
  classes: 'character-creation',
  equipment: 'equipment-system',
  'equipment-system': 'equipment-system',
  items: 'equipment-system',
  core: 'core-rules',
  'core-rules': 'core-rules',
  rules: 'core-rules'
};

const RulesPage = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const params = useParams();

  const updateCodexUrl = useCallback((categoryId, subcategoryId, classDetail = null) => {
    const isCodexRoute = location.pathname.startsWith('/codex');
    const isRulesRoute = location.pathname.startsWith('/rules');
    if (isCodexRoute) {
      if (classDetail) {
        navigate(`/codex/classes/${encodeURIComponent(classDetail)}`, { replace: false });
      } else {
        navigate(`/codex/${categoryId}/${subcategoryId}`, { replace: false });
      }
    } else if (isRulesRoute) {
      if (classDetail) {
        navigate(`/rules/classes/${encodeURIComponent(classDetail)}`, { replace: false });
      } else {
        navigate(`/rules/${categoryId}/${subcategoryId}`, { replace: false });
      }
    } else {
      navigate(`/?section=rules&category=${categoryId}&sub=${subcategoryId}${classDetail ? `&class=${encodeURIComponent(classDetail)}` : ''}`, { replace: false });
    }
  }, [location.pathname, navigate]);

  const [selectedCategory, setSelectedCategory] = useState(() => {
    if (params?.category) {
      return CODEX_CATEGORY_ALIASES[params.category.toLowerCase()] || params.category;
    }
    if (typeof window !== 'undefined') {
      const sp = new URLSearchParams(window.location.search);
      const cat = sp.get('category');
      if (cat) return CODEX_CATEGORY_ALIASES[cat.toLowerCase()] || cat;
    }
    return 'core-rules';
  });

  const [selectedSubcategory, setSelectedSubcategory] = useState(() => {
    if (params?.subcategory) return params.subcategory;
    if (params?.category?.toLowerCase() === 'bestiary') return 'bestiary';
    if (params?.category?.toLowerCase() === 'lexicon') return 'lexicon';
    if (params?.category?.toLowerCase() === 'classes') return 'classes';
    if (params?.category && (CODEX_CATEGORY_ALIASES[params.category.toLowerCase()] || params.category) === 'travel-exploration') return 'wilderness-survival';
    if (typeof window !== 'undefined') {
      const sp = new URLSearchParams(window.location.search);
      return sp.get('sub') || 'game-overview';
    }
    return 'game-overview';
  });

  const [selectedClassDetail, setSelectedClassDetail] = useState(() => {
    if (params?.classId) return params.classId;
    if (typeof window !== 'undefined') {
      const sp = new URLSearchParams(window.location.search);
      return sp.get('class') || null;
    }
    return null;
  });

  // Sync state when location.search or route params change (e.g. browser Back / Forward buttons)
  useEffect(() => {
    const sp = new URLSearchParams(location.search);
    const cat = params?.category || sp.get('category');
    const sub = params?.subcategory || sp.get('sub');
    const cls = params?.classId || sp.get('class');

    if (cat) {
      const resolvedCat = CODEX_CATEGORY_ALIASES[cat.toLowerCase()] || cat;
      setSelectedCategory(resolvedCat);
      if (!sub) {
        if (cat.toLowerCase() === 'bestiary') setSelectedSubcategory('bestiary');
        else if (cat.toLowerCase() === 'lexicon') setSelectedSubcategory('lexicon');
        else if (cat.toLowerCase() === 'classes') setSelectedSubcategory('classes');
        else if (resolvedCat === 'travel-exploration') setSelectedSubcategory('wilderness-survival');
      }
    }
    if (sub) {
      setSelectedSubcategory(sub);
    }
    if (cls !== undefined) {
      setSelectedClassDetail(cls || null);
    }
  }, [location.search, params?.category, params?.subcategory, params?.classId]);



  const [activeTab, setActiveTab] = useState(null);



  const [popoutCategory, setPopoutCategory] = useState(null);



  const [popoutPosition, setPopoutPosition] = useState({ top: 0, left: 0 });



  const [tablePages, setTablePages] = useState({});



  const [loadedClassData, setLoadedClassData] = useState(null);



  const [isLoadingClassData, setIsLoadingClassData] = useState(false);



  const buttonRefs = useRef({});

  // Last visited topic per tome (Laws vs Lore) for the switcher
  const lastTomeTopicRef = useRef({
    laws: { categoryId: 'core-rules', subcategoryId: 'game-overview' },
    lore: { categoryId: 'world-lore', subcategoryId: 'introduction' }
  });



  const [activeSectionTab, setActiveSectionTab] = useState(0);


  const [showSearch, setShowSearch] = useState(false);
  const { data: rulesCategories, isLoading: rulesLoading } = useGameData('rules');
  const { data: loreData } = useGameData('lore');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchFilter, setSearchFilter] = useState('all');
  const [searchResults, setSearchResults] = useState([]);
  const [selectedResultIndex, setSelectedResultIndex] = useState(0);
  const [showRulesBrowse, setShowRulesBrowse] = useState(false);
  const [browseCategory, setBrowseCategory] = useState(null);
  const searchInputRef = useRef(null);
  const searchModalRef = useRef(null);

  // Search functionality
  const openSearch = useCallback((initialQuery = '') => {
    setShowSearch(true);
    setSearchQuery(initialQuery);
    setSelectedResultIndex(0);
    if (initialQuery.trim().length >= 2) {
      setSearchResults(searchRulesIndex(initialQuery, searchFilter));
    } else {
      setSearchResults([]);
    }
    requestAnimationFrame(() => {
      searchInputRef.current?.focus();
      if (initialQuery) {
        searchInputRef.current?.select();
      }
    });
  }, [searchFilter]);

  const closeSearch = useCallback(() => {
    setShowSearch(false);
    setSearchQuery('');
    setSearchResults([]);
    setSelectedResultIndex(0);
  }, []);

  const handleSearchChange = useCallback((e) => {
    const val = e.target.value;
    setSearchQuery(val);
    setSelectedResultIndex(0);
    if (val.trim().length >= 2) {
      setSearchResults(searchRulesIndex(val, searchFilter));
    } else {
      setSearchResults([]);
    }
  }, [searchFilter]);

  const handleFilterChange = useCallback((filter) => {
    setSearchFilter(filter);
    setSelectedResultIndex(0);
    if (searchQuery.trim().length >= 2) {
      setSearchResults(searchRulesIndex(searchQuery, filter));
    }
  }, [searchQuery]);

  const handleSearchResultClick = useCallback((result) => {
    if (!result) return;
    closeSearch();

    let targetSubcategory = result.subcategoryId;
    if (result.categoryId === 'world-lore' && result.subcategoryId === 'regions') {
      targetSubcategory = 'regional-overview';
    }

    lastTomeTopicRef.current[result.categoryId === 'world-lore' ? 'lore' : 'laws'] = {
      categoryId: result.categoryId,
      subcategoryId: targetSubcategory
    };

    setSelectedCategory(result.categoryId);
    setSelectedSubcategory(targetSubcategory);
    setSelectedClassDetail(result.classId || null);
    setActiveTab(result.tabId || null);
    setActiveSectionTab(result.sectionIndex !== null && result.sectionIndex >= 0 ? result.sectionIndex : 0);

    updateCodexUrl(result.categoryId, targetSubcategory, result.classId || null);

    // Smooth scroll and pulse highlight the target
    requestAnimationFrame(() => {
      setTimeout(() => {
        let targetEl = null;

        if (result.sectionIndex !== null && result.sectionIndex >= 0) {
          targetEl = document.getElementById(`section-${result.sectionIndex}`) ||
                     document.querySelector(`[data-section-index="${result.sectionIndex}"]`);
        }

        if (!targetEl && result.displayTitle) {
          const titleEls = Array.from(document.querySelectorAll('.rules-section-card-title, .rules-section-title, h2, h3, h4, .lexicon-term-title, .bestiary-card-name'));
          const cleanTitle = result.displayTitle.toLowerCase().trim();
          targetEl = titleEls.find(el => el.textContent.toLowerCase().includes(cleanTitle))?.closest('.rules-section-card, .rules-section, .lexicon-card, .bestiary-card, .rules-summary-box, article');
        }

        if (!targetEl && result.termId) {
          targetEl = document.getElementById(`term-${result.termId}`) || document.querySelector(`[data-term-id="${result.termId}"]`);
        }

        if (targetEl) {
          targetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
          targetEl.classList.remove('rules-search-target-highlight');
          void targetEl.offsetWidth; // trigger reflow
          targetEl.classList.add('rules-search-target-highlight');
          setTimeout(() => {
            if (targetEl) targetEl.classList.remove('rules-search-target-highlight');
          }, 3000);
        } else {
          const mainEl = document.querySelector('.rules-main') || document.querySelector('.rules-content-area');
          if (mainEl) mainEl.scrollTop = 0;
        }
      }, 240);
    });
  }, [closeSearch, navigate]);

  const handleSearchKeyDown = useCallback((e) => {
    if (e.key === 'Escape') {
      closeSearch();
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedResultIndex(prev => Math.min(prev + 1, Math.max(0, searchResults.length - 1)));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedResultIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter' && searchResults.length > 0) {
      e.preventDefault();
      const target = searchResults[selectedResultIndex] || searchResults[0];
      handleSearchResultClick(target);
    }
  }, [searchResults, selectedResultIndex, closeSearch, handleSearchResultClick]);

  // Global shortcut Ctrl+K and / to open search
  useEffect(() => {
    const handleGlobalKeyDown = (e) => {
      if ((e.ctrlKey || e.metaKey) && (e.key === 'k' || e.key === 'K')) {
        e.preventDefault();
        openSearch();
      } else if (e.key === '/' && !['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName)) {
        e.preventDefault();
        openSearch();
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [openSearch]);

  // Close search modal on outside click or Escape
  useEffect(() => {
    if (!showSearch) return;

    const handleKey = (e) => {
      if (e.key === 'Escape') closeSearch();
    };

    const handleClickOutside = (e) => {
      if (searchModalRef.current && !searchModalRef.current.contains(e.target)) {
        closeSearch();
      }
    };

    document.addEventListener('keydown', handleKey);
    document.addEventListener('mousedown', handleClickOutside);

    return () => {
      document.removeEventListener('keydown', handleKey);
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showSearch, closeSearch]);







  // Lazy load class data when a class is selected



  useEffect(() => {



    if (!selectedClassDetail) {



      setLoadedClassData(null);



      return;



    }







    // Check cache first



    if (classDataCache.has(selectedClassDetail)) {



      setLoadedClassData(classDataCache.get(selectedClassDetail));



      return;



    }







    // Load class data



    const loader = CLASS_DATA_LOADERS[selectedClassDetail];



    if (!loader) {



      setLoadedClassData(null);



      return;



    }







    setIsLoadingClassData(true);



    loader()



      .then(data => {



        classDataCache.set(selectedClassDetail, data);



        setLoadedClassData(data);



      })



      .catch(error => {



        console.error(`Failed to load class data for ${selectedClassDetail}:`, error);



        setLoadedClassData(null);



      })



      .finally(() => {



        setIsLoadingClassData(false);



      });



  }, [selectedClassDetail]);







  // Handle subcategory selection



  const handleSubcategoryClick = (categoryId, subcategoryId, sectionIndex = null, tabId = null) => {
    // Map legacy or shorthand subcategory IDs to correct ones
    let targetSubcategory = subcategoryId;
    if (categoryId === 'world-lore' && subcategoryId === 'regions') {
      targetSubcategory = 'regional-overview';
    }

    // Remember the last topic per tome so the Laws/Lore switcher can return to it
    lastTomeTopicRef.current[categoryId === 'world-lore' ? 'lore' : 'laws'] = {
      categoryId,
      subcategoryId: targetSubcategory
    };

    setSelectedCategory(categoryId);
    setSelectedSubcategory(targetSubcategory);
    setSelectedClassDetail(null);
    setActiveTab(tabId);
    setActiveSectionTab(sectionIndex !== null && sectionIndex >= 0 ? sectionIndex : 0);
    setShowSearch(false);

    // Push URL search query so browser Back and Forward buttons navigate between topics
    updateCodexUrl(categoryId, targetSubcategory);







    // Scroll to section if specified, otherwise scroll content to top



    if (sectionIndex !== null && sectionIndex >= 0) {



      requestAnimationFrame(() => {



        setTimeout(() => {



          const contentArea = document.querySelector('.rules-content-area');



          const sectionEl = document.getElementById(`section-${sectionIndex}`);



          if (contentArea && sectionEl) {



            const top = sectionEl.offsetTop - 24;



            contentArea.scrollTo({ top, behavior: 'smooth' });



          }



        }, 180);



      });



    } else {



      const mainEl = document.querySelector('.rules-main');



      if (mainEl) mainEl.scrollTop = 0;



    }



  };







  // Handle breadcrumb navigation



  // Which tome the current topic belongs to — Lore is the world-lore category, everything else is Laws.
  const activeTome = selectedCategory === 'world-lore' ? 'lore' : 'laws';

  const handleTomeChange = (tome) => {
    if (tome === activeTome) return;
    const target = lastTomeTopicRef.current[tome] || lastTomeTopicRef.current.laws;
    handleSubcategoryClick(target.categoryId, target.subcategoryId);
  };

  const handleBreadcrumbClick = (breadcrumbType) => {



    if (breadcrumbType === 'rules') {



      // Navigate to the active tome's overview



      if (activeTome === 'lore') {

        handleSubcategoryClick('world-lore', 'introduction');

      } else {

        handleSubcategoryClick('core-rules', 'game-overview');

      }



    } else if (breadcrumbType === 'character-creation') {



      // Navigate to character creation overview



      handleSubcategoryClick('character-creation', 'creation-overview');



    }



  };







  // Handle class detail selection
  const handleClassClick = (className) => {
    setSelectedCategory('character-creation');
    setSelectedSubcategory('classes');
    setSelectedClassDetail(className);

    // Push class detail to browser history so Back button goes back to classes list
    updateCodexUrl('character-creation', 'classes', className);
  };

  // Handle back to classes list
  const handleBackToClasses = () => {
    setSelectedClassDetail(null);
    updateCodexUrl('character-creation', 'classes');
  };

  // Handle internal rules link clicks for interactive navigation



  const handleContentClick = useCallback((e) => {



    const link = e.target.closest('.rules-link');



    if (link) {



      e.preventDefault();



      const category = link.getAttribute('data-category');



      const subcategory = link.getAttribute('data-subcategory');



      if (subcategory === 'classes') {



        const className = normalizeClassName(link.textContent);



        if (className) {



          handleClassClick(className);



          const mainEl = document.querySelector('.rules-main');



          if (mainEl) {



            mainEl.scrollTop = 0;



          }



          return;



        }



      }



      if (category && subcategory) {



        handleSubcategoryClick(category, subcategory);



        const mainEl = document.querySelector('.rules-main');



        if (mainEl) {



          mainEl.scrollTop = 0;



        }



      }



    }



  }, []);







  // Get current content



  const currentContent = useMemo(() => {

    return getRuleContent(selectedCategory, selectedSubcategory);

  }, [selectedCategory, selectedSubcategory, rulesCategories]);



  // Get breadcrumbs

  const breadcrumbs = useMemo(() => {

    const category = (rulesCategories || []).find(c => c.id === selectedCategory);

    const subcategory = category?.subcategories.find(s => s.id === selectedSubcategory);

    return {

      category: category?.name || '',

      subcategory: subcategory?.name || ''

    };

  }, [selectedCategory, selectedSubcategory, rulesCategories]);



  // Categories for the active tome. The Lore tome renders its topics directly in
  // the rail (see loreCategory), so only the Laws categories are mapped as popout groups.
  const filteredCategories = useMemo(() => {

    const all = rulesCategories || [];

    if (activeTome === 'lore') return [];

    return all.filter(c => c.id !== 'world-lore');

  }, [rulesCategories, activeTome]);

  const loreCategory = useMemo(
    () => (rulesCategories || []).find(c => c.id === 'world-lore') || null,
    [rulesCategories]
  );

  // Browse sheet keeps a single World Lore entry per tome.
  const browseCategories = useMemo(
    () => (activeTome === 'lore' ? (loreCategory ? [loreCategory] : []) : filteredCategories),
    [activeTome, loreCategory, filteredCategories]
  );

  // Lore that lives outside this compendium: account codex, campaigns, journal and books.
  const loreArchives = useMemo(() => ([
    { id: 'world-codex', label: 'World Codex', icon: 'fas fa-atlas', tab: 'maps' },
    { id: 'campaign-chronicles', label: 'Campaign Chronicles', icon: 'fas fa-scroll', tab: 'campaigns' },
    { id: 'journal', label: 'Journal', icon: 'fas fa-feather-alt', tab: 'journal' },
    { id: 'books', label: 'Books', icon: 'fas fa-book-bookmark', tab: 'books' }
  ]), []);

  const { isAuthenticated } = useAuthStore();
  const canOpenAccountLore = isAuthenticated;







  // Reset table pagination when the viewed content changes



  useEffect(() => {



    setTablePages({});



  }, [currentContent]);







  // Render a table



  const renderTable = (table, tableIdx, sectionTheme = 'narrative') => {



    const tableKey = table.id || table.title || `table-${tableIdx}`;



    const currentPage = tablePages[tableKey] || 0;



    



    return (



      <RulesTable



        key={tableKey}



        table={table}



        tableIdx={tableIdx}



        sectionTheme={sectionTheme}



        selectedSubcategory={selectedSubcategory}



        handleClassClick={handleClassClick}



        currentPage={currentPage}



        onPageChange={(nextPage) => {



          setTablePages(prev => ({



            ...prev,



            [tableKey]: nextPage



          }));



        }}



      />



    );



  };







  // Render content sections



  const renderSections = (sections, sectionTheme) => {



    if (!sections) return null;



    const theme = sectionTheme || 'narrative';







    const currentSubcategory = (rulesCategories || [])



      .find(cat => cat.id === selectedCategory)



      ?.subcategories?.find(sub => sub.id === selectedSubcategory);







    // Filter out sections that are just rotating tips or have no content



    const validSections = sections.filter(s => s.type !== 'rotating-tips' && (s.content || s.title));



    const tipsSections = sections.filter(s => s.type === 'rotating-tips');







    // Render active tabbed section



    let renderedSections = null;



    if (validSections.length <= 1 || currentSubcategory?.disableSectionTabs) {



      renderedSections = validSections.map((section, idx) => (



        <RulesSectionItem



          key={idx}



          section={section}



          idx={idx}



          theme={theme}



          selectedSubcategory={selectedSubcategory}



          isLast={idx === validSections.length - 1}



          handleClassClick={handleClassClick}



          handleSubcategoryClick={handleSubcategoryClick}



        />



      ));



    } else {



      const activeIdx = activeSectionTab < validSections.length ? activeSectionTab : 0;



      const activeSection = validSections[activeIdx];



      renderedSections = (



        <div className="page-fade-in" key={activeIdx}>



          <RulesSectionItem



            section={activeSection}



            idx={activeIdx}



            theme={theme}



            selectedSubcategory={selectedSubcategory}



            isLast={true}



            handleClassClick={handleClassClick}



            handleSubcategoryClick={handleSubcategoryClick}



          />



        </div>



      );



    }







    // Render rotating tips at the bottom if present



    return (



      <>



        {renderedSections}



        {tipsSections.map((section, idx) => (



          <RulesSectionItem



            key={`tip-${idx}`}



            section={section}



            idx={idx}



            theme={theme}



            selectedSubcategory={selectedSubcategory}



            isLast={idx === tipsSections.length - 1}



            handleClassClick={handleClassClick}



            handleSubcategoryClick={handleSubcategoryClick}



          />



        ))}



      </>



    );



  };







  // Render tabbed content



  const renderTabbedContent = (tabs, sectionTheme) => {



    const currentTab = activeTab || tabs[0].id;



    const currentTabData = tabs.find(t => t.id === currentTab);







    return (



      <div className="rules-tabs-container">



        <div className="rules-tabs">



          {tabs.map(tab => (



            <button



              key={tab.id}



              className={`rules-tab ${currentTab === tab.id ? 'active' : ''}`}



              onClick={() => setActiveTab(tab.id)}



            >



              {tab.name}



            </button>



          ))}



        </div>



        <div className="rules-tab-content">



          {currentTabData?.description && (



            <div className="rules-tab-description" dangerouslySetInnerHTML={{ __html: sanitizeHtml(processMarkdown(currentTabData.description)) }} />



          )}



          {currentTabData?.sections && renderSections(currentTabData.sections, sectionTheme)}



          {currentTabData?.tables && currentTabData.tables.map((t, i) => renderTable(t, i, sectionTheme))}



        </div>



      </div>



    );



  };







  // Render main content



  const renderContent = () => {



    if (!currentContent) {



      return (



        <div className="rules-no-content">



          <i className="fas fa-book-open"></i>



          <p>Select a topic from the sidebar to view rules</p>



        </div>



      );



    }







    // Check if this subcategory should use a custom component



    const currentCategory = (rulesCategories || [])



      .find(cat => cat.id === selectedCategory);



    const currentSubcategory = currentCategory



      ?.subcategories?.find(sub => sub.id === selectedSubcategory);







    // If viewing a class detail page



    if (selectedClassDetail && selectedSubcategory === 'classes') {



      return (



        <div className="rules-content-area class-detail-view">
          {isLoadingClassData ? (



            <div className="rules-loading">



              <i className="fas fa-spinner fa-spin"></i>



              <p>Loading tradition data...</p>



            </div>



          ) : loadedClassData ? (

            <Suspense fallback={
              <div className="rules-loading">
                <i className="fas fa-spinner fa-spin"></i>
                <p>Loading tradition data...</p>
              </div>
            }>
              <ClassDetailDisplay 
                classData={loadedClassData} 
                onBack={handleBackToClasses} 
                onSelectClass={handleClassClick}
              />
            </Suspense>

          ) : (



            <div className="rules-no-content">



              <i className="fas fa-exclamation-triangle"></i>



              <p>Tradition data for {selectedClassDetail} is not yet available.</p>



              <p>This tradition will be added in a future update.</p>



            </div>



          )}



        </div>



      );



    }







    // Determine if using custom component



    const isUsingCustomComponent = currentSubcategory?.useCustomComponent;



    const sectionTheme = currentSubcategory?.theme || 'narrative';







    return (



      <div className={`rules-content-area ${isUsingCustomComponent ? 'custom-component-view' : ''}`}>
        <RulesHeroBanner



          title={currentContent.title}



          subtitle={currentContent.description}



          badge={breadcrumbs.category?.toUpperCase()}



          badgeIcon={currentSubcategory?.icon || currentCategory?.icon || 'fas fa-book-open'}



          theme={sectionTheme}



          quickTiles={currentSubcategory?.quickFacts}



        />







        {/* Antique Scribe's Index Tabs Bar */}



        {!isUsingCustomComponent && !currentSubcategory?.disableSectionTabs && currentContent.sections && currentContent.sections.length > 1 && (() => {



          const validSections = currentContent.sections.filter(s => s.title && s.type !== 'rotating-tips' && (s.content || s.title));



          if (validSections.length <= 1) return null;



          return (



            <div className="rpg-tabs-bar">



              {validSections.map((section, idx) => {



                const displayTitle = section.title.split(':')[0].split('(')[0].replace(/this rulebook/i, '').trim();



                return (



                  <React.Fragment key={idx}>



                    {idx > 0 && <span className="rpg-tab-divider">✦</span>}



                    <button



                      className={`rpg-custom-tab ${activeSectionTab === idx ? 'active' : ''}`}



                      onClick={() => setActiveSectionTab(idx)}



                      title={section.title}



                    >



                      <span className="rpg-tab-label">{displayTitle}</span>



                    </button>



                  </React.Fragment>



                );



              })}



            </div>



          );



        })()}











        {/* Quick reference tiles */}



        {!isUsingCustomComponent && currentSubcategory?.quickFacts && (



          <RulesQuickTiles tiles={currentSubcategory.quickFacts} />



        )}







        {/* Summary box */}



        {!isUsingCustomComponent && currentSubcategory?.summary && (



          <RulesSummaryBox items={currentSubcategory.summary} />



        )}







        {!isUsingCustomComponent && currentContent.sections && renderSections(currentContent.sections, sectionTheme)}







        {/* Custom component: Classes grid replaces the old table */}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'classes' && !selectedClassDetail && (
          <Suspense fallback={
            <div className="rules-loading">
              <i className="fas fa-spinner fa-spin"></i>
              <p>Loading classes...</p>
            </div>
          }>
            <ClassesDisplay onSelectClass={handleClassClick} />
          </Suspense>
        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'races' && (



          <Suspense fallback={



            <div className="rules-loading">



              <i className="fas fa-spinner fa-spin"></i>



              <p>Loading race selector...</p>



            </div>



          }>



            <RaceSelector />



          </Suspense>



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'character-backgrounds' && (



          <BackgroundsDisplay />



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'skills' && (



          <SkillsDisplay variant="advanced" />



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'weapons' && (



          <WeaponsRulesDisplay />



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'languages' && (



          <LanguagesDisplay />



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'advanced-travel' && (



          <AdvancedTravelDisplay />



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'timeline' && (



          <Suspense fallback={



            <div className="rules-loading">



              <i className="fas fa-spinner fa-spin"></i>



              <p>Loading timeline...</p>



            </div>



          }>



            <TimelineDisplay />



          </Suspense>



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'bestiary' && (



          <Suspense fallback={



            <div className="rules-loading">



              <i className="fas fa-spinner fa-spin"></i>



              <p>Loading bestiary...</p>



            </div>



          }>



            <BestiaryDisplay />



          </Suspense>



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'lexicon' && (



          <Suspense fallback={



            <div className="rules-loading">



              <i className="fas fa-spinner fa-spin"></i>



              <p>Loading lexicon...</p>



            </div>



          }>



            <LexiconDisplay />



          </Suspense>



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'dramatis-personae' && (



          <Suspense fallback={



            <div className="rules-loading">



              <i className="fas fa-spinner fa-spin"></i>



              <p>Loading notable figures...</p>



            </div>



          }>



            <DramatisPersonaeDisplay />



          </Suspense>



        )}



        {currentSubcategory?.useCustomComponent && selectedSubcategory === 'class-origins' && (



          <Suspense fallback={



            <div className="rules-loading">



              <i className="fas fa-spinner fa-spin"></i>



              <p>Loading class origins...</p>



            </div>



          }>



            <ClassOriginsDisplay />



          </Suspense>



        )}











        {/* Render tables */}



        {!isUsingCustomComponent && currentContent.tables && currentContent.tables.map((table, idx) => renderTable(table, idx, sectionTheme))}







        {/* Render tabs if present (only if not using custom component) */}



        {!currentSubcategory?.useCustomComponent && currentContent.tabs && renderTabbedContent(currentContent.tabs, sectionTheme)}

        {/* Archival colophon folio marker at natural end of text */}
        <div className="rules-folio-footer">
          <span className="rules-folio-footer-text">✦ Mythrill VTT Codex • Folio LXXVI ✦</span>
        </div>



      </div>



    );



  };







  // Close popout when clicking outside and recalculate position on scroll/resize



  useEffect(() => {



    if (!popoutCategory) return;







    const handleClickOutside = (event) => {



      // Don't close if clicking on the button that opened it or the popout itself



      if (event.target.closest('.rules-nav-popout') || event.target.closest('.rules-nav-category-btn')) {



        return;



      }



      setPopoutCategory(null);



    };







    let rafId = 0;

    const updatePopoutPosition = () => {



      // Recalculate position on resize to keep popout visible



      const categoryId = popoutCategory;



      const button = buttonRefs.current[categoryId];



      if (button) {



        const rect = button.getBoundingClientRect();



        const category = filteredCategories.find(c => c.id === categoryId);



        const subCount = category ? category.subcategories.length : 8;



        const popoutWidth = 300;



        const popoutHeight = Math.min(window.innerHeight - 120, 60 + subCount * 44);



        const gap = 12;



        const padding = 10;



        const headerHeight = 70; // Height of the header







        let left = rect.right + gap;



        let top = rect.top + rect.height / 2;







        if (left + popoutWidth > window.innerWidth - padding) {



          left = rect.left - popoutWidth - gap;



        }



        if (left < padding) {



          left = padding;



        }



        if (left + popoutWidth > window.innerWidth - padding) {



          left = window.innerWidth - popoutWidth - padding;



        }







        const halfHeight = popoutHeight / 2;



        // Ensure popout doesn't go under the header



        if (top - halfHeight < headerHeight + padding) {



          top = halfHeight + headerHeight + padding;



        } else if (top + halfHeight > window.innerHeight - padding) {



          top = window.innerHeight - halfHeight - padding;



        }







        setPopoutPosition(prev => (
          Math.abs(prev.top - top) < 1 && Math.abs(prev.left - left) < 1
            ? prev
            : { top, left }
        ));



      }



    };







    // The popout re-anchors on scroll/resize; batch those into a single
    // animation frame so raw scroll events do not re-render the codex.
    const handleResize = () => {
      if (rafId) return;
      rafId = requestAnimationFrame(() => {
        rafId = 0;
        updatePopoutPosition();
      });
    };

    // Delay to avoid immediate closure when opening



    const timeoutId = setTimeout(() => {



      document.addEventListener('mousedown', handleClickOutside);



      document.addEventListener('touchstart', handleClickOutside);



      window.addEventListener('resize', handleResize);



      window.addEventListener('scroll', handleResize, { capture: true, passive: true });



    }, 10);







    return () => {



      clearTimeout(timeoutId);
      cancelAnimationFrame(rafId);



      document.removeEventListener('mousedown', handleClickOutside);



      document.removeEventListener('touchstart', handleClickOutside);



      window.removeEventListener('resize', handleResize);



      window.removeEventListener('scroll', handleResize, true);



    };



  }, [popoutCategory]);











  const renderTomeSwitcher = (variant) => (
    <div
      className={`rules-tome-switcher ${variant === 'mobile' ? 'rules-tome-switcher-mobile' : 'rules-tome-switcher-desktop'}`}
      role="group"
      aria-label="Laws and Lore"
    >
      <button
        type="button"
        aria-pressed={activeTome === 'laws'}
        className={`rules-tome-tab ${activeTome === 'laws' ? 'active' : ''}`}
        onClick={() => handleTomeChange('laws')}
        title="Laws — rules, systems, and character creation"
      >
        <i className="fas fa-scale-balanced"></i>
        <span className="rules-tome-label">Laws</span>
      </button>
      <span className="rules-tome-spine" aria-hidden="true">
        <i className="fas fa-book-open"></i>
      </span>
      <button
        type="button"
        aria-pressed={activeTome === 'lore'}
        className={`rules-tome-tab ${activeTome === 'lore' ? 'active' : ''}`}
        onClick={() => handleTomeChange('lore')}
        title="Lore — world, history, peoples, and bestiary"
      >
        <i className="fas fa-scroll"></i>
        <span className="rules-tome-label">Lore</span>
      </button>
    </div>
  );

  return (



    <div className="rules-page">



      {/* Sidebar Navigation - Always Collapsed */}



      <aside className="rules-sidebar collapsed">



        {/* Navigation Tree */}



        <nav className="rules-nav collapsed">



          {/* Search Trigger Button */}



          <div className="rules-sidebar-search-trigger">



            <button



              className="rules-search-trigger-btn"



              onClick={() => openSearch()}



              title="Search the Codex"



              aria-label="Search the Codex"



            >



              <i className="fas fa-search"></i>



            </button>



          </div>



          <button



            type="button"



            className="rules-browse-trigger"



            onClick={() => { setBrowseCategory(null); setShowRulesBrowse(true); }}



            title="Browse all sections"



            aria-label="Browse all sections"



          >



            <i className="fas fa-compass"></i>



            <span>Browse</span>



          </button>



          {/* Lore rail — one button per World Lore topic (14 topics used to hide
              behind a single globe button) plus the lore that lives elsewhere. */}
          {activeTome === 'lore' && (
            <>
              {(loreCategory?.subcategories || []).map(sub => (
                <div key={sub.id} className="rules-nav-category">
                  <button
                    type="button"
                    className={`rules-nav-category-btn ${selectedCategory === 'world-lore' && selectedSubcategory === sub.id && !selectedClassDetail ? 'active-category' : ''}`}
                    onClick={() => handleSubcategoryClick('world-lore', sub.id)}
                    title={sub.name}
                    aria-label={sub.name}
                    data-active={selectedCategory === 'world-lore' && selectedSubcategory === sub.id ? 'true' : 'false'}
                  >
                    <i className={`${sub.icon || 'fas fa-scroll'} rules-nav-icon`}></i>
                  </button>
                </div>
              ))}

              {canOpenAccountLore && (
                <>
                  <div className="rules-nav-divider" aria-hidden="true" />
                  {loreArchives.map(entry => (
                    <div key={entry.id} className="rules-nav-category">
                      <button
                        type="button"
                        className="rules-nav-category-btn rules-nav-archive-btn"
                        onClick={() => navigate(`/account?tab=${entry.tab}`)}
                        title={`${entry.label} — continues in your account`}
                        aria-label={entry.label}
                      >
                        <i className={`${entry.icon} rules-nav-icon`}></i>
                      </button>
                    </div>
                  ))}
                </>
              )}
            </>
          )}

          {filteredCategories.map(category => (



            <div key={category.id} className="rules-nav-category">



              <div style={{ position: 'relative' }}>



                <button



                  ref={(el) => (buttonRefs.current[category.id] = el)}



                  className={`rules-nav-category-btn ${selectedCategory === category.id ? 'active-category' : ''}`}



                  onClick={(e) => {



                    e.stopPropagation();



                    const button = e.currentTarget;



                    const rect = button.getBoundingClientRect();



                    const isMobile = window.innerWidth <= 768;



                    



                    if (isMobile) {



                      // On mobile, always show from bottom



                      setPopoutPosition({



                        top: window.innerHeight,



                        left: 0



                      });



                    } else {



                      // Desktop positioning logic



                      // Popout dimensions (dynamic & accurate)



                      const popoutWidth = 300; // max-width from CSS (240-300px)



                      const subCount = category.subcategories ? category.subcategories.length : 8;



                      const popoutHeight = Math.min(window.innerHeight - 120, 60 + subCount * 44);



                      const gap = 12;



                      const padding = 10; // minimum padding from screen edges



                      const headerHeight = 70; // Height of the header



                      



                      // Calculate desired position (to the right of button)



                      let left = rect.right + gap;



                      let top = rect.top + rect.height / 2;



                      



                      // Check if popout would go off right edge



                      if (left + popoutWidth > window.innerWidth) {



                        // If it would go off-screen, position it to the left of the button instead



                        left = rect.left - popoutWidth - gap;



                      }



                      



                      // Ensure it doesn't go off left edge either



                      if (left < padding) {



                        left = padding;



                      }



                      



                      // Ensure it doesn't go off right edge



                      if (left + popoutWidth > window.innerWidth - padding) {



                        left = window.innerWidth - popoutWidth - padding;



                      }



                      



                      // Check vertical bounds - keep popout centered on button but within viewport



                      // Ensure popout doesn't go under the header



                      const halfHeight = popoutHeight / 2;



                      if (top - halfHeight < headerHeight + padding) {



                        // Too close to top (or would go under header), adjust down



                        top = halfHeight + headerHeight + padding;



                      } else if (top + halfHeight > window.innerHeight - padding) {



                        // Too close to bottom, adjust up



                        top = window.innerHeight - halfHeight - padding;



                      }



                      



                      // Calculate position relative to viewport



                      setPopoutPosition({



                        top: top,



                        left: left



                      });



                    }



                    // Always show popout menu



                    setPopoutCategory(popoutCategory === category.id ? null : category.id);



                  }}



                  title={category.name}



                  data-active={selectedCategory === category.id ? 'true' : 'false'}



                >



                  <i className={`${category.icon || 'fas fa-circle'} rules-nav-icon`}></i>



                </button>




                {/* Popout orb menu - portaled to body to escape ancestor mask-image/overflow clipping
                    (.rules-nav.collapsed uses mask-image + overflow:hidden which would otherwise
                    trap a position:fixed descendant inside its 58px scrollable bar) */}




                {popoutCategory === category.id && createPortal(

                  <div className="rules-nav-popout-backdrop" onClick={() => setPopoutCategory(null)}>

                  <div

                    className="rules-nav-popout"



                    style={{



                      top: `${popoutPosition.top}px`,



                      left: `${popoutPosition.left}px`



                    }}

                    onClick={(e) => e.stopPropagation()}



                  >



                    <div className="rules-nav-popout-header">



                      <i className={category.icon}></i>



                      <span>{category.name}</span>



                    </div>



                    <div className="rules-nav-popout-body">



                      {category.subcategories.map(sub => (



                        <button



                          key={sub.id}



                          className={`rules-nav-popout-item ${



                            selectedCategory === category.id && selectedSubcategory === sub.id && !selectedClassDetail



                              ? 'active'



                              : ''



                          }`}



                          onClick={(e) => {



                            e.stopPropagation();



                            handleSubcategoryClick(category.id, sub.id);



                            setPopoutCategory(null);



                          }}



                        >



                          <i className={sub.icon}></i>



                          <span>{sub.name}</span>



                        </button>



                      ))}
                    </div>




                  </div>
                  </div>,
                  document.body

                )}




              </div>







            </div>



          ))}



        </nav>



        {/* The Two Tomes — Laws / Lore switcher (slim view toolbar) */}
        {renderTomeSwitcher('mobile')}

      </aside>







      {/* Main Content Area */}



      <main className="rules-main" onClick={handleContentClick}>

        {/* Top Navigation & Quick Search Bar */}
        <div className="rules-top-bar">
          <div className="rules-breadcrumbs">
            <button
              className={`rules-breadcrumb rules-breadcrumb-link rules-breadcrumb-tome tome-${activeTome}`}
              onClick={() => handleBreadcrumbClick('rules')}
              aria-label={`Navigate to ${activeTome === 'lore' ? 'Lore' : 'Laws'} overview`}
            >
              <i className={`fas ${activeTome === 'lore' ? 'fa-scroll' : 'fa-scale-balanced'}`}></i>
              {activeTome === 'lore' ? 'Lore' : 'Laws'}
            </button>
            <i className="fas fa-chevron-right"></i>
            {breadcrumbs.category === 'Character Creation' ? (
              <button
                className="rules-breadcrumb rules-breadcrumb-link"
                onClick={() => handleBreadcrumbClick('character-creation')}
                aria-label="Navigate to Character Creation overview"
              >
                {breadcrumbs.category}
              </button>
            ) : (
              <span className="rules-breadcrumb">{breadcrumbs.category}</span>
            )}
            <i className="fas fa-chevron-right"></i>
            {selectedClassDetail && selectedSubcategory === 'classes' ? (
              <button
                className="rules-breadcrumb rules-breadcrumb-link"
                onClick={handleBackToClasses}
                aria-label="Navigate to Classes list"
              >
                {breadcrumbs.subcategory}
              </button>
            ) : (
              <span className="rules-breadcrumb active">{breadcrumbs.subcategory}</span>
            )}
            {selectedClassDetail && selectedSubcategory === 'classes' && (
              <>
                <i className="fas fa-chevron-right"></i>
                <span className="rules-breadcrumb active">{selectedClassDetail}</span>
              </>
            )}
          </div>

          {/* The Two Tomes — Laws (mechanics) and Lore (world) */}
          {renderTomeSwitcher('desktop')}

          <div
            className="rules-header-quick-search"
            onClick={() => openSearch()}
            role="button"
            tabIndex={0}
            title="Search Codex (Ctrl + K)"
            aria-label="Search Codex"
          >
            <i className="fas fa-search"></i>
            <span className="rules-quick-search-placeholder">Search lore, rules, spells, classes...</span>
            <kbd className="rules-quick-search-shortcut">Ctrl K</kbd>
          </div>
        </div>

        {/* Content */}
        {renderContent()}
      </main>

      {/* Search Modal Overlay */}
      {showSearch && (
        <div className="rules-search-overlay">
          <div className="rules-search-modal" ref={searchModalRef}>
            <div className="rules-search-header">
              <h3 className="rules-search-title">
                <i className="fas fa-scroll"></i>
                Search the Mythrill Codex
              </h3>
              <button className="rules-search-close" onClick={closeSearch} aria-label="Close search">
                <i className="fas fa-times"></i>
              </button>
            </div>

            <div className="rules-search-body">
              <div className="rules-search-input-wrapper">
                <span className="rules-search-input-icon">
                  <i className="fas fa-search"></i>
                </span>
                <input
                  ref={searchInputRef}
                  type="text"
                  className="rules-search-input"
                  placeholder="Search rules, lore, creatures, combat, classes, terms..."
                  value={searchQuery}
                  onChange={handleSearchChange}
                  onKeyDown={handleSearchKeyDown}
                />
                {searchQuery && (
                  <button className="rules-search-input-clear" onClick={() => { setSearchQuery(''); setSearchResults([]); searchInputRef.current?.focus(); }} aria-label="Clear search">
                    <i className="fas fa-times"></i>
                  </button>
                )}
              </div>

              {/* Filter Chips Bar */}
              <div className="rules-search-filter-chips">
                {SEARCH_FILTERS.map(f => (
                  <button
                    key={f.id}
                    className={`rules-search-chip ${searchFilter === f.id ? 'active' : ''}`}
                    onClick={() => handleFilterChange(f.id)}
                  >
                    <i className={f.icon}></i>
                    <span>{f.label}</span>
                  </button>
                ))}
              </div>

              <div className="rules-search-results">
                {searchQuery.trim().length < 2 ? (
                  <div className="rules-search-hint">
                    <i className="fas fa-search"></i>
                    <p>Type at least 2 characters to search across all lore, mechanics, and rules</p>
                    <div className="rules-search-examples">
                      <span>Try searching:</span>
                      <button type="button" className="rules-search-example-pill" onClick={() => openSearch('keth')}>keth</button>
                      <button type="button" className="rules-search-example-pill" onClick={() => openSearch('range measurement')}>range measurement</button>
                      <button type="button" className="rules-search-example-pill" onClick={() => openSearch('difficulty die')}>difficulty die</button>
                      <button type="button" className="rules-search-example-pill" onClick={() => openSearch('first contract')}>first contract</button>
                    </div>
                  </div>
                ) : searchResults.length === 0 ? (
                  <div className="rules-search-empty">
                    <i className="fas fa-book-dead"></i>
                    <p>No records found matching "{searchQuery}" in {searchFilter === 'all' ? 'the codex' : searchFilter}</p>
                  </div>
                ) : (
                  <div className="rules-search-results-list">
                    {searchResults.map((result, idx) => (
                      <button
                        key={result.id}
                        className={`rules-search-result-item ${selectedResultIndex === idx ? 'selected' : ''}`}
                        onClick={() => handleSearchResultClick(result)}
                        onMouseEnter={() => setSelectedResultIndex(idx)}
                      >
                        <div className="rules-search-result-header">
                          <div className="rules-search-result-breadcrumb">
                            <span>{result.categoryName}</span>
                            {result.subcategoryName && (
                              <>
                                <i className="fas fa-chevron-right"></i>
                                <span>{result.subcategoryName}</span>
                              </>
                            )}
                            {result.tabName && (
                              <>
                                <i className="fas fa-chevron-right"></i>
                                <span className="rules-search-result-section">{result.tabName}</span>
                              </>
                            )}
                            {result.sectionTitle && result.sectionIndex >= 0 && !result.tabName && (
                              <>
                                <i className="fas fa-chevron-right"></i>
                                <span className="rules-search-result-section">{result.sectionTitle}</span>
                              </>
                            )}
                          </div>
                          {result.badge && (
                            <span
                              className="rules-search-badge"
                              style={{
                                backgroundColor: `${result.badgeColor || '#d4af37'}22`,
                                color: result.badgeColor || '#d4af37',
                                borderColor: `${result.badgeColor || '#d4af37'}55`
                              }}
                            >
                              {result.badge}
                            </span>
                          )}
                        </div>

                        <div className="rules-search-result-title">
                          {highlightSearchMatch(result.displayTitle, searchQuery)}
                        </div>

                        {result.snippet && (
                          <div className="rules-search-result-preview">
                            {highlightSearchMatch(result.snippet, searchQuery)}
                          </div>
                        )}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {searchResults.length > 0 && (
              <div className="rules-search-footer">
                <span>{searchResults.length} result{searchResults.length !== 1 ? 's' : ''} found</span>
                <span className="rules-search-footer-hint">
                  <kbd>↑</kbd> <kbd>↓</kbd> navigate <span className="footer-dot">•</span> <kbd>Enter</kbd> select <span className="footer-dot">•</span> <kbd>Esc</kbd> close
                </span>
              </div>
            )}
          </div>
        </div>
      )}

      {showRulesBrowse && createPortal(



        <div className="rules-browse-overlay" onClick={() => setShowRulesBrowse(false)}>



          <div className="rules-browse-sheet" onClick={(e) => e.stopPropagation()}>



            <div className="rules-browse-header">



              {browseCategory ? (



                <button



                  type="button"



                  className="rules-browse-back"



                  onClick={() => setBrowseCategory(null)}



                  aria-label="Back to categories"



                >



                  <i className="fas fa-chevron-left"></i>



                </button>



              ) : (



                <span className="rules-browse-title">



                  <i className="fas fa-compass"></i> Browse {activeTome === 'lore' ? 'the Lore' : 'the Laws'}



                </span>



              )}



              {browseCategory && (



                <span className="rules-browse-title">



                  <i className={browseCategory.icon}></i> {browseCategory.name}



                </span>



              )}



              <button



                type="button"



                className="rules-browse-close"



                onClick={() => setShowRulesBrowse(false)}



                aria-label="Close browse"



              >



                <i className="fas fa-xmark"></i>



              </button>



            </div>



            <div className="rules-browse-body">



              {!browseCategory ? (
                <>

                  {browseCategories.map(cat => (



                  <button



                    type="button"



                    key={cat.id}



                    className={`rules-browse-item ${selectedCategory === cat.id ? 'active' : ''}`}



                    onClick={() => setBrowseCategory(cat)}



                  >



                    <i className={cat.icon || 'fas fa-circle'}></i>



                    <span>{cat.name}</span>



                    <i className="fas fa-chevron-right rules-browse-chevron"></i>



                  </button>



                ))}



                {activeTome === 'lore' && canOpenAccountLore && (
                  <div className="rules-browse-archives">

                    <span className="rules-browse-archives-label">More lore across Mythrill</span>

                    {loreArchives.map(entry => (
                      <button
                        type="button"
                        key={entry.id}
                        className="rules-browse-item"
                        onClick={() => {
                          navigate(`/account?tab=${entry.tab}`);
                          setShowRulesBrowse(false);
                        }}
                      >

                        <i className={entry.icon}></i>

                        <span>{entry.label}</span>

                        <i className="fas fa-arrow-up-right-from-square rules-browse-chevron"></i>

                      </button>
                    ))}

                  </div>
                )}

                </>
              ) : (



                browseCategory.subcategories.map(sub => (



                  <button



                    type="button"



                    key={sub.id}



                    className={`rules-browse-item ${selectedCategory === browseCategory.id && selectedSubcategory === sub.id && !selectedClassDetail ? 'active' : ''}`}



                    onClick={() => {



                      handleSubcategoryClick(browseCategory.id, sub.id);



                      setShowRulesBrowse(false);



                      setBrowseCategory(null);



                    }}



                  >



                    <i className={sub.icon}></i>



                    <span>{sub.name}</span>



                  </button>



                ))



              )}



            </div>



          </div>



        </div>,



        document.body



      )}



    </div>



  );



};







export default RulesPage;

