// Helper to extract specific passive traits for a specialization
export const getSpecPassives = (fullSpec, sharedPassive = null) => {
    const passives = [];

    // Specific Spec Passives
    if (fullSpec?.passiveAbilities && Array.isArray(fullSpec.passiveAbilities)) {
        fullSpec.passiveAbilities.forEach(p => {
            if (p && !passives.some(existing => existing.name?.toLowerCase() === p.name?.toLowerCase())) {
                passives.push({
                    name: p.name,
                    description: p.description,
                    tier: p.tier || 'Specialization Passive',
                    sharedBy: p.sharedBy,
                    uniqueTo: p.uniqueTo,
                    isShared: p.tier === 'Path Passive'
                });
            }
        });
    }

    if (fullSpec?.specPassive) {
        if (!passives.some(existing => existing.name?.toLowerCase() === fullSpec.specPassive.name?.toLowerCase())) {
            passives.push({
                name: fullSpec.specPassive.name,
                description: fullSpec.specPassive.description,
                tier: 'Specialization Passive',
                isShared: false
            });
        }
    }

    if (fullSpec?.passiveAbility) {
        if (!passives.some(existing => existing.name?.toLowerCase() === fullSpec.passiveAbility.name?.toLowerCase())) {
            passives.push({
                name: fullSpec.passiveAbility.name,
                description: fullSpec.passiveAbility.description,
                tier: 'Path Passive',
                isShared: false
            });
        }
    }

    // Shared Path / Tradition Passive (if defined)
    if (sharedPassive && !passives.some(existing => existing.name?.toLowerCase() === sharedPassive.name?.toLowerCase())) {
        passives.push({
            name: sharedPassive.name,
            description: sharedPassive.description,
            tier: 'Shared Path Passive',
            isShared: true
        });
    }

    return passives;
};

// Helper to extract specializations & talent lists for a class
export const getTalentTreesForClass = (className) => {
    if (!className) return [];
    let classData = CLASS_SPECIALIZATIONS[className];
    let resolvedName = className;
    if (!classData) {
        const normalized = className.toLowerCase().replace(/[-_]/g, ' ');
        const entry = Object.entries(CLASS_SPECIALIZATIONS).find(([key]) =>
            key.toLowerCase() === normalized || key.toLowerCase().replace(/[-_]/g, ' ') === normalized
        );
        if (entry) {
            classData = entry[1];
            resolvedName = entry[0];
        }
    }
    if (!classData) return [];

    const fullClassData = ALL_CLASSES_DATA[resolvedName] || Object.entries(ALL_CLASSES_DATA).find(([k]) =>
        k.toLowerCase() === resolvedName.toLowerCase().replace(/[-_]/g, ' ')
    )?.[1];

    const sharedPassive = fullClassData?.specializations?.passiveAbility || null;

    return classData.specializations.map((spec, index) => {
        const fullSpec = fullClassData?.specializations?.specs?.find(s =>
            s.id === spec.id || s.name?.toLowerCase() === spec.name?.toLowerCase()
        ) || fullClassData?.specializations?.specs?.[index];

        const passives = getSpecPassives(fullSpec, sharedPassive);

        return {
            id: spec.id,
            name: spec.name,
            description: spec.description || fullSpec?.description || '',
            color: spec.color || fullSpec?.color || '#d4af37',
            icon: spec.icon || fullSpec?.icon,
            theme: fullSpec?.theme || '',
            playstyle: fullSpec?.playstyle || '',
            passives: passives,
            sharedPassive: sharedPassive,
            backdrop: getTreeBackdrop(resolvedName, spec.id) || getFallbackBackground(index),
            fallbackBackground: getFallbackBackground(index),
            talents: getTalentsForSpec(resolvedName, spec.id) || []
        };
    });
};

// Helper to determine node tier (1..7)
export const getNodeTier = (node) => {
    if (!node) return 1;
    const t = talentTier(node);
    if (t >= 1 && t <= 7) return t;
    if (node?.position?.y != null) {
        return Math.min(7, Math.max(1, Math.floor(node.position.y) + 1));
    }
    return 1;
};

// Points required in the current tree to unlock a given tier (5 points per tier, WoW Classic style)
export const getRequiredPointsForTier = (tier) => Math.max(0, (tier - 1) * (TALENT_SYSTEM?.POINTS_PER_TIER_GATE || 5));

// Candidate nodes may carry their own authored point gate (RI-1 Chaos Weaver);
// fall back to the generic 5-per-tier ladder when they do not.
export const getNodePointGate = (talent) => (
    Number.isFinite(talent?.requiresPoints) ? talent.requiresPoints : getRequiredPointsForTier(getNodeTier(talent))
);

// Tree board layout constraints — keep nodes legible and guaranteed non-overlapping.
const MAX_BOARD_WIDTH = 1000;   // desktop cap so the board does not stretch endlessly
const MIN_NODE_SIZE = 42;       // smallest tappable/legible node before we scroll instead
const NODE_GAP = 10;            // minimum empty space between two neighbouring nodes

// Cooldown unit label — the talent system is round-based; pluralize properly.
const formatCooldownUnit = (value, unit) => {
    const u = unit || 'rounds';
    if (u === 'round' || u === 'rounds') return Number(value) === 1 ? 'round' : 'rounds';
    return u;
};

// Format spell meta chips (AP, Resource, Range, CD, Reaction, Trigger)
const renderSpellMetaChips = (spell) => {
    if (!spell) return null;
    const isReaction = spell.spellType === 'REACTION' || spell.actionType === 'reaction' ||
        /^(as a )?reaction/i.test(spell.description || '') || /reaction\s*\(/i.test(spell.description || '');
    const isPassive = !isReaction && (spell.spellType === 'PASSIVE' || spell.actionType === 'passive' || /^passive/i.test(spell.description || ''));

    const triggerText = spell.reactionTrigger || spell.trigger || extractTriggerFromDescription(spell.description);

    const costs = [];
    if (spell.resourceCosts) {
        Object.entries(spell.resourceCosts).forEach(([key, val]) => {
            if (val && val.baseAmount > 0) {
                const cleanKey = key.replace(/([A-Z])/g, ' $1').toLowerCase();
                costs.push(`${val.baseAmount} ${cleanKey}`);
            }
        });
    }

    return (
        <div className="talent-meta-chips-row">
            {isReaction ? (
                <span className="talent-meta-chip chip-reaction">
                    <i className="fas fa-bolt-lightning"></i>
                    <span>Reaction</span>
                </span>
            ) : isPassive ? (
                <span className="talent-meta-chip chip-passive">
                    <i className="fas fa-shield-halved"></i>
                    <span>Passive</span>
                </span>
            ) : (
                <span className="talent-meta-chip chip-action">
                    <i className="fas fa-hand-sparkles"></i>
                    <span>Action</span>
                </span>
            )}

            {!isPassive && (spell.actionPoints > 0 || (spell.actionPoints === 0 && !isReaction)) && (
                <span className="talent-meta-chip chip-ap">
                    <i className="fas fa-bolt"></i>
                    <span>{spell.actionPoints} AP</span>
                </span>
            )}

            {costs.length > 0 && (
                <span className="talent-meta-chip chip-resource">
                    <i className="fas fa-gem"></i>
                    <span>{costs.join(' + ')}</span>
                </span>
            )}

            {spell.range && spell.range > 0 && (
                <span className="talent-meta-chip chip-range">
                    <i className="fas fa-location-crosshairs"></i>
                    <span>{spell.rangeType === 'melee' ? 'Melee (5 ft)' : `${spell.range} ft Range`}</span>
                </span>
            )}

            {!isPassive && spell.cooldownValue && (
                <span className="talent-meta-chip chip-cd">
                    <i className="fas fa-clock"></i>
                    <span>{spell.cooldownValue} {formatCooldownUnit(spell.cooldownValue, spell.cooldownUnit)} CD</span>
                </span>
            )}

            {triggerText && (
                <span className="talent-meta-chip chip-trigger" title={triggerText}>
                    <i className="fas fa-reply-all"></i>
                    <span>Trigger: {triggerText}</span>
                </span>
            )}
        </div>
    );
};

// Dynamic description for tooltips & inspector
const getDynamicDescription = (talent, currentRank, readOnly = false) => {
    if (!talent) return null;
    const hasSpellData = Boolean(talent.spell);

    if (!hasSpellData) {
        return <div className="talent-desc-text">{talent.description || ''}</div>;
    }

    const maxRank = talent.maxRanks || 1;
    const parts = [];

    if (readOnly) {
        const baseSpell = resolveTalentSpell(talent, 1);
        parts.push(
            <div key="rank-1" className="talent-desc-block current-rank-block">
                <div className="talent-rank-header current">
                    <span className="rank-header-indicator"></span>
                    <span className="rank-header-title">{baseSpell?.spellType === 'PASSIVE' ? 'Passive' : 'Spell'} — Rank 1 {maxRank === 1 ? '(Base & Max)' : '(Base Effect)'}</span>
                </div>
                <div className="talent-desc-text">{baseSpell?.description}</div>
            </div>
        );

        for (let r = 2; r <= maxRank; r++) {
            const upgradedSpell = resolveTalentSpell(talent, r);
            parts.push(
                <div key={`rank-${r}`} className="talent-desc-block next-rank-block">
                    <div className="talent-rank-header next">
                        <i className="fas fa-arrow-turn-up next-icon"></i>
                        <span className="rank-header-title">Rank {r} Scaling:</span>
                    </div>
                    <div className="talent-desc-text">{upgradedSpell?.description}</div>
                </div>
            );
        }

        return <div className="talent-desc-container">{parts}</div>;
    }

    if (currentRank > 0) {
        const currentSpell = resolveTalentSpell(talent, currentRank);
        parts.push(
            <div key="current" className="talent-desc-block current-rank-block">
                <div className="talent-rank-header current">
                    <span className="rank-header-indicator"></span>
                    <span className="rank-header-title">{currentSpell?.spellType === 'PASSIVE' ? 'Passive Effect' : 'Spell Effect'} — Rank {currentRank}</span>
                </div>
                <div className="talent-desc-text">{currentSpell?.description}</div>
            </div>
        );
    }

    if (currentRank < maxRank) {
        const nextSpell = resolveTalentSpell(talent, currentRank + 1);
        parts.push(
            <div key="next" className="talent-desc-block next-rank-block">
                <div className="talent-rank-header next">
                    <i className="fas fa-arrow-turn-up next-icon"></i>
                    <span className="rank-header-title">{currentRank === 0 ? 'Rank 1 Effect:' : 'Next Rank Upgrade (+1):'}</span>
                </div>
                <div className="talent-desc-text">{nextSpell?.description}</div>
            </div>
        );
    }

    return <div className="talent-desc-container">{parts}</div>;
};

// Plain-text spell chip summary used by the copy/print build sheet
const formatSpellChipsText = (spell) => {
    if (!spell) return '';
    const isReaction = spell.spellType === 'REACTION' || spell.actionType === 'reaction';
    const isPassive = !isReaction && (spell.spellType === 'PASSIVE' || spell.actionType === 'passive');
    const parts = [isReaction ? 'Reaction' : isPassive ? 'Passive' : 'Action'];

    if (!isPassive) {
        if (spell.actionPoints != null) parts.push(`${spell.actionPoints} AP`);
        if (spell.resourceCosts) {
            Object.entries(spell.resourceCosts).forEach(([key, val]) => {
                if (val && val.baseAmount > 0) {
                    parts.push(`${val.baseAmount} ${key.replace(/([A-Z])/g, ' $1').toLowerCase()}`);
                }
            });
        }
        if (spell.range) parts.push(spell.rangeType === 'melee' ? 'Melee (5 ft)' : `${spell.range} ft`);
        if (spell.cooldownValue) parts.push(`${spell.cooldownValue} ${formatCooldownUnit(spell.cooldownValue, spell.cooldownUnit)} CD`);
    }

    return parts.join(' · ');
};

const escapeHtml = (value) => String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

/**
 * Plain-text "at the table" summary of a character's learned talents.
 * Used by Copy Build Text and the printable build sheet.
 */
export const buildBuildText = ({ trees = [], talents = {}, characterClass = '', level = 1, primarySpecialization = '' }) => {
    const spent = trees.reduce(
        (total, tree) => total + (tree.talents || []).reduce((sum, t) => sum + (talents[t.id] || 0), 0),
        0
    );
    const available = Math.min((level || 1) * 5, 50);
    const lines = [
        `MYTHRILL BUILD — ${characterClass || 'Character'} (Level ${level || 1})`,
        `Talent Points: ${spent}/${available}`
    ];

    const primary = trees.find((tree) => tree.id === primarySpecialization);
    if (primary) lines.push(`Primary Specialization: ${primary.name}`);
    lines.push('');

    trees.forEach((tree) => {
        const learned = (tree.talents || []).filter((t) => (talents[t.id] || 0) > 0);
        if (learned.length === 0) return;
        const treePoints = learned.reduce((sum, t) => sum + (talents[t.id] || 0), 0);
        lines.push(`[${tree.name}] — ${treePoints} pts`);
        learned.forEach((talent) => {
            const rank = talents[talent.id] || 0;
            const spell = resolveTalentSpell(talent, rank);
            const chips = formatSpellChipsText(spell);
            lines.push(`• ${talent.name} — Rank ${rank}/${talent.maxRanks || 1}${chips ? ` (${chips})` : ''}`);
            if (spell?.description) lines.push(`  ${spell.description}`);
        });
        lines.push('');
    });

    return lines.join('\n').trim();
};

export const TalentTreeContent = ({
    customClass = null,
    selectedTreeIndex = null,
    onTreeSelect = null,
    hideHeader = false,
    readOnly = false
}) => {
    const characterStore = useCharacterStore();
    const characterClass = customClass || characterStore.class;
    const storedGamblerTalents = characterClass === 'Gambler' ? characterStore.talents : null;
    const level = characterStore.level || 1;
    const currentCharacterId = characterStore.currentCharacterId;
    const primarySpecialization = characterStore.primarySpecialization || '';
    const setPrimarySpecialization = characterStore.setPrimarySpecialization;

    const [internalTree, setInternalTree] = useState(0);
    const [talents, setTalents] = useState({});
    const [unlearnError, setUnlearnError] = useState(null);
    const [hoveredTalentId, setHoveredTalentId] = useState(null);
    const [selectedTalentId, setSelectedTalentId] = useState(null);
    const [gridDims, setGridDims] = useState({ width: 440, height: 540 });
    const [isTouchLayout, setIsTouchLayout] = useState(false);
    const [helpOpen, setHelpOpen] = useState(() => {
        try {
            const stored = window.localStorage.getItem('mythrill:talentHelpOpen');
            return stored === null ? true : stored === '1';
        } catch {
            return true;
        }
    });
    const [copyState, setCopyState] = useState(null);

    const boardRef = useRef(null);

    // Touch/narrow layouts inspect first and allocate from the sticky action bar;
    // desktop keeps click-to-learn + right-click-refund.
    useEffect(() => {
        const mediaQuery = typeof window.matchMedia === 'function' ? window.matchMedia('(pointer: coarse)') : null;
        const update = () => {
            const coarse = mediaQuery ? mediaQuery.matches : false;
            const narrow = typeof window.innerWidth === 'number' && window.innerWidth <= 768;
            setIsTouchLayout(coarse || narrow);
        };
        update();
        window.addEventListener('resize', update);
        if (mediaQuery?.addEventListener) mediaQuery.addEventListener('change', update);
        else if (mediaQuery?.addListener) mediaQuery.addListener(update);
        return () => {
            window.removeEventListener('resize', update);
            if (mediaQuery?.removeEventListener) mediaQuery.removeEventListener('change', update);
            else if (mediaQuery?.removeListener) mediaQuery.removeListener(update);
        };
    }, []);

    const activeTree = selectedTreeIndex !== null ? selectedTreeIndex : internalTree;

    const handleTreeChange = (idx) => {
        setSelectedTalentId(null);
        if (onTreeSelect) {
            onTreeSelect(idx);
        } else {
            setInternalTree(idx);
        }
    };

    // Sync talents from store on mount / character switch (only when interactive)
    useEffect(() => {
        if (!readOnly) {
            setTalents(useCharacterStore.getState().talents || {});
        } else {
            setTalents({});
        }
    }, [currentCharacterId, readOnly, characterClass, storedGamblerTalents]);

    // Responsive container sizing. We always measure the scroll container (never
    // the board itself) so a board that grows wider than the viewport can expose
    // horizontal scrolling without feeding its own size back into the layout.
    useEffect(() => {
        const getScrollParent = () =>
            boardRef.current?.closest('.talent-tree-scroll-container') || boardRef.current?.parentElement || null;

        const updateDims = () => {
            const scrollParent = getScrollParent();
            if (!scrollParent) return;
            const cs = window.getComputedStyle(scrollParent);
            const padX = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
            const padY = (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
            const availableW = Math.max(240, scrollParent.clientWidth - padX);
            const availableH = Math.max(300, scrollParent.clientHeight - padY);
            setGridDims(prev => (
                prev.width === availableW && prev.height === availableH
                    ? prev
                    : { width: availableW, height: availableH }
            ));
        };

        updateDims();
        let ro = null;
        const scrollParent = getScrollParent();
        if (typeof ResizeObserver !== 'undefined' && scrollParent) {
            ro = new ResizeObserver(updateDims);
            ro.observe(scrollParent);
        } else {
            window.addEventListener('resize', updateDims);
        }

        return () => {
            if (ro) ro.disconnect();
            window.removeEventListener('resize', updateDims);
        };
    }, [activeTree]);

    const trees = getTalentTreesForClass(characterClass);
    const currentTree = trees[activeTree];

    // Total points spent across all trees
    const pointsSpent = trees.reduce((total, tree) => {
        return total + tree.talents.reduce((sum, talent) => sum + (talents[talent.id] || 0), 0);
    }, 0);

    // Points spent in current active tree
    const treePointsSpent = (currentTree?.talents || []).reduce((sum, talent) => sum + (talents[talent.id] || 0), 0);

    const availablePoints = Math.min((level || 1) * 5, 50);
    const pointsRemaining = availablePoints - pointsSpent;

    // Spellbook & Library synchronization
    const syncTalentSpell = (talent, newRank) => {
        if (!talent?.spell) return;
        const spellbook = useSpellbookStore.getState();
        const stableId = talent.grantId || talent.passiveSpellId || `talent-spell-${talent.id}`;
        const existing = (spellbook.spells || []).find(s => s.id === stableId);

        const currentLib = loadLibraryFromStorage() || { spells: [] };
        const libIndex = (currentLib.spells || []).findIndex(s => s.id === stableId);

        if (newRank <= 0) {
            if (existing) spellbook.deleteSpell(stableId);
            if (libIndex !== -1) {
                currentLib.spells.splice(libIndex, 1);
                saveLibraryToStorage(currentLib);
            }
            return;
        }

        // Grant nodes own their canonical class spell identity (RI-1):
        // materialise the authored record itself so ACTION type, AP cost,
        // targeting and typed mechanics are preserved instead of passing
        // through the legacy passive-oriented talent converter. Nodes
        // without a grant keep the legacy `talent-spell-${id}` identity.
        const canonicalGrant = talent.grantId || talent.passiveSpellId
            ? CHAOS_WEAVER_PROJECTED_SPELLS_BY_ID[stableId] || ALL_CLASSES_DATA[characterClass]?.spells?.find(spell => spell.id === stableId)
            : null;
        const librarySpell = canonicalGrant
            ? {
                 ...canonicalGrant,
                 ...(talent.passiveSpellId ? {
                     description: talent.rankValues?.[newRank - 1]?.text || canonicalGrant.description,
                     learnedRankValues: talent.rankValues?.[newRank - 1]?.values || {}
                 } : {}),
                source: 'talent',
                talentId: talent.id,
                talentRank: newRank,
                maxRanks: talent.maxRanks || 1,
                isCustom: false
            }
            : convertTalentSpellToLibrarySpell(talent, newRank);
        if (!librarySpell) return;
        if (talent.grantId && !canonicalGrant) librarySpell.id = talent.grantId;

        if (existing) {
            spellbook.updateSpell(stableId, librarySpell);
        } else {
            spellbook.addSpell(librarySpell);
        }

        if (libIndex !== -1) {
            currentLib.spells[libIndex] = librarySpell;
        } else {
            currentLib.spells = currentLib.spells || [];
            currentLib.spells.push(librarySpell);
        }
        saveLibraryToStorage(currentLib);
    };

    // Prerequisite check shared by allocation and locked-node styling
    const arePrerequisitesMet = (talent) => {
        if (!talent.requires) return true;
        const reqIds = Array.isArray(talent.requires) ? talent.requires : [talent.requires];
        const isReqMet = (reqId) => {
            const prereq = currentTree?.talents?.find(t => t.id === reqId);
            return prereq && (talents[reqId] || 0) >= (prereq.maxRanks || 1);
        };
        return talent.requiresAll ? reqIds.every(isReqMet) : reqIds.some(isReqMet);
    };

    // Validation to learn
    const canLearnTalent = (talent) => {
        if (pointsSpent >= availablePoints) return false;

        // Tier Gatekeeping: explicit authored gate when present, else (tier - 1) * 5 points in this tree
        const requiredInTree = getNodePointGate(talent);
        if (treePointsSpent < requiredInTree) return false;
        if (Number.isFinite(talent.minLevel) && level < talent.minLevel) return false;

        return arePrerequisitesMet(talent);
    };

    // A node is visually "locked" when it has no ranks and the tier gate or a
    // prerequisite blocks it (distinct from simply being out of points).
    const isNodeLocked = (talent) => {
        if ((talents[talent.id] || 0) > 0) return false;
        if (treePointsSpent < getNodePointGate(talent)) return true;
        if (Number.isFinite(talent.minLevel) && level < talent.minLevel) return true;
        return !arePrerequisitesMet(talent);
    };

    // Validation to unlearn
    const canUnlearnTalent = (talentId) => {
        const currentRanks = talents[talentId] || 0;
        if (currentRanks <= 0) return { canUnlearn: false, reason: 'none' };

        const sim = { ...talents, [talentId]: currentRanks - 1 };
        if (sim[talentId] === 0) delete sim[talentId];

        for (const tree of trees) {
            // 1. Check prerequisite dependencies
            for (const t of tree.talents) {
                if ((sim[t.id] || 0) > 0 && t.requires) {
                    const reqIds = Array.isArray(t.requires) ? t.requires : [t.requires];
                    if (t.requiresAll) {
                        const allMet = reqIds.every(reqId => {
                            const p = tree.talents.find(node => node.id === reqId);
                            return (sim[reqId] || 0) >= (p?.maxRanks || 1);
                        });
                        if (!allMet) return { canUnlearn: false, reason: 'prerequisite' };
                    } else {
                        const anyMet = reqIds.some(reqId => {
                            const p = tree.talents.find(node => node.id === reqId);
                            return (sim[reqId] || 0) >= (p?.maxRanks || 1);
                        });
                        if (!anyMet) return { canUnlearn: false, reason: 'prerequisite' };
                    }
                }
            }

            // 2. Check tier gatekeeping
            for (let T = 2; characterClass !== 'Gambler' && T <= 7; T++) {
                const hasTalentsAtOrAboveT = tree.talents.some(t => {
                    const tTier = getNodeTier(t);
                    return tTier >= T && (sim[t.id] || 0) > 0;
                });

                if (hasTalentsAtOrAboveT) {
                    const pointsBelowT = tree.talents
                        .filter(t => getNodeTier(t) < T)
                        .reduce((sum, t) => sum + (sim[t.id] || 0), 0);

                    const requiredBelowT = getRequiredPointsForTier(T);
                    if (pointsBelowT < requiredBelowT) {
                        return {
                            canUnlearn: false,
                            reason: 'tier_gate',
                            requiredTier: T,
                            requiredPoints: requiredBelowT
                        };
                    }
                }
            }

            // 3. Explicit authored gates (candidate nodes bring their own ladder)
            for (const t of tree.talents) {
                if ((sim[t.id] || 0) > 0 && Number.isFinite(t.requiresPoints)) {
                    const pointsBelow = tree.talents
                        .filter(n => characterClass === 'Gambler' ? n.id !== t.id : (n.position?.y ?? 0) < (t.position?.y ?? 0))
                        .reduce((sum, n) => sum + (sim[n.id] || 0), 0);
                    if (pointsBelow < t.requiresPoints) {
                        return {
                            canUnlearn: false,
                            reason: 'tier_gate',
                            requiredTier: getNodeTier(t),
                            requiredPoints: t.requiresPoints
                        };
                    }
                }
            }
        }
        return { canUnlearn: true };
    };

    const handleTalentClick = (talentId, talent) => {
        setSelectedTalentId(talentId);
        if (readOnly) return;
        if (!canLearnTalent(talent)) return;
        const currentRanks = talents[talentId] || 0;
        if (currentRanks >= (talent.maxRanks || 1)) return;

        const newTalents = { ...talents, [talentId]: currentRanks + 1 };
        setTalents(newTalents);
        useCharacterStore.getState().setTalents(newTalents);

        // The tree receiving the first talent point unlocks its innate passives and becomes the primary specialization
        const totalPointsBefore = Object.values(talents).reduce((sum, v) => sum + (v || 0), 0);
        const currentPrimary = characterStore.primarySpecialization;
        if (!currentPrimary || totalPointsBefore === 0) {
            const targetTree = trees.find(tr => tr.talents?.some(t => t.id === talentId));
            if (targetTree) {
                useCharacterStore.getState().setPrimarySpecialization?.(targetTree.id);
            }
        }

        syncTalentSpell(talent, currentRanks + 1);
    };

    const handleTalentRightClick = (e, talentId, talent) => {
        e.preventDefault();
        setSelectedTalentId(talentId);
        if (readOnly) return;
        const unlearnCheck = canUnlearnTalent(talentId);
        if (!unlearnCheck.canUnlearn) {
            const errorMsg = unlearnCheck.reason === 'tier_gate'
                ? `Cannot refund: Tier ${unlearnCheck.requiredTier} talents require at least ${unlearnCheck.requiredPoints} points invested in lower tiers.`
                : 'Cannot refund: other learned talents depend on this prerequisite.';
            setUnlearnError({
                message: errorMsg,
                position: { x: e.clientX, y: e.clientY }
            });
            setTimeout(() => setUnlearnError(null), 2800);
            return;
        }

        const currentRanks = talents[talentId] || 0;
        if (currentRanks <= 0) return;

        const newTalents = { ...talents };
        if (currentRanks - 1 === 0) {
            delete newTalents[talentId];
        } else {
            newTalents[talentId] = currentRanks - 1;
        }

        setTalents(newTalents);
        useCharacterStore.getState().setTalents(newTalents);

        // If no talent points are invested anywhere, reset primary specialization
        const totalPointsAfter = Object.values(newTalents).reduce((sum, v) => sum + (v || 0), 0);
        if (totalPointsAfter === 0) {
            useCharacterStore.getState().setPrimarySpecialization?.('');
        }

        syncTalentSpell(talent, currentRanks - 1);
    };

    const resetTalents = () => {
        const spellbook = useSpellbookStore.getState();
        const grantIds = trees
            .flatMap(tree => tree.talents)
            .map(t => t.grantId || t.passiveSpellId)
            .filter(Boolean);
        const isTalentOwnedSpell = (id) => Boolean(id) && (id.startsWith('talent-spell-') || grantIds.includes(id));

        (spellbook.spells || [])
            .filter(s => isTalentOwnedSpell(s.id))
            .forEach(s => spellbook.deleteSpell(s.id));

        const currentLib = loadLibraryFromStorage();
        if (currentLib?.spells) {
            currentLib.spells = currentLib.spells.filter(s => !isTalentOwnedSpell(s.id));
            saveLibraryToStorage(currentLib);
        }

        setTalents({});
        useCharacterStore.getState().setTalents({});
        useCharacterStore.getState().setPrimarySpecialization?.('');
    };

    const toggleHelp = () => {
        setHelpOpen((prev) => {
            const next = !prev;
            try {
                window.localStorage.setItem('mythrill:talentHelpOpen', next ? '1' : '0');
            } catch {
                // Storage unavailable (private mode) — keep the in-memory state.
            }
            return next;
        });
    };

    const buildSummaryText = () => buildBuildText({
        trees,
        talents,
        characterClass,
        level,
        primarySpecialization
    });

    const handleCopyBuild = async () => {
        const text = buildSummaryText();
        try {
            if (navigator.clipboard?.writeText) {
                await navigator.clipboard.writeText(text);
            } else {
                const area = document.createElement('textarea');
                area.value = text;
                area.setAttribute('readonly', '');
                area.style.position = 'fixed';
                area.style.opacity = '0';
                document.body.appendChild(area);
                area.select();
                document.execCommand('copy');
                document.body.removeChild(area);
            }
            setCopyState('copied');
        } catch {
            setCopyState('error');
        }
        setTimeout(() => setCopyState(null), 2200);
    };

    const handlePrintBuild = () => {
        const printWindow = window.open('', '_blank', 'width=820,height=920');
        if (!printWindow) {
            setCopyState('error');
            setTimeout(() => setCopyState(null), 2200);
            return;
        }

        const available = Math.min((level || 1) * 5, 50);
        const spent = trees.reduce(
            (total, tree) => total + (tree.talents || []).reduce((sum, t) => sum + (talents[t.id] || 0), 0),
            0
        );
        const primary = trees.find((tree) => tree.id === primarySpecialization);

        const treeSections = trees.map((tree) => {
            const learned = (tree.talents || []).filter((t) => (talents[t.id] || 0) > 0);
            if (learned.length === 0) return '';
            const treePoints = learned.reduce((sum, t) => sum + (talents[t.id] || 0), 0);
            const rows = learned.map((talent) => {
                const rank = talents[talent.id] || 0;
                const spell = resolveTalentSpell(talent, rank);
                const chips = formatSpellChipsText(spell);
                return `<div class="talent">
                    <div class="talent-head"><span class="talent-name">${escapeHtml(talent.name)}</span>
                    <span class="talent-rank">Rank ${rank}/${talent.maxRanks || 1}</span>
                    ${chips ? `<span class="talent-chips">${escapeHtml(chips)}</span>` : ''}</div>
                    ${spell?.description ? `<div class="talent-desc">${escapeHtml(spell.description)}</div>` : ''}
                </div>`;
            }).join('');
            return `<section><h2>${escapeHtml(tree.name)} <span class="pts">${treePoints} pts</span></h2>${rows}</section>`;
        }).join('');

        const html = `<!doctype html><html><head><meta charset="utf-8" />
<title>${escapeHtml(characterClass)} — Talent Build</title>
<style>
    body { font-family: Georgia, 'Times New Roman', serif; color: #111; margin: 26px; line-height: 1.45; }
    h1 { font-size: 21px; margin: 0 0 2px; }
    .meta { color: #444; font-size: 13px; margin-bottom: 14px; }
    h2 { font-size: 15px; margin: 18px 0 8px; border-bottom: 1.5px solid #888; padding-bottom: 3px; }
    h2 .pts { font-size: 12px; color: #666; font-weight: normal; }
    .talent { margin: 0 0 10px; page-break-inside: avoid; }
    .talent-head { display: flex; flex-wrap: wrap; gap: 8px; align-items: baseline; }
    .talent-name { font-weight: bold; }
    .talent-rank { font-size: 12px; color: #555; }
    .talent-chips { font-size: 12px; color: #444; font-style: italic; }
    .talent-desc { font-size: 13px; margin-top: 2px; }
    .foot { margin-top: 18px; font-size: 11px; color: #777; border-top: 1px solid #ccc; padding-top: 6px; }
</style></head><body>
    <h1>${escapeHtml(characterClass)} — Talent Build</h1>
    <div class="meta">Level ${level || 1} · Talent Points ${spent}/${available}${primary ? ` · Primary Specialization: ${escapeHtml(primary.name)}` : ''}</div>
    ${treeSections}
    <div class="foot">Mythrill VTT · generated build sheet</div>
</body></html>`;

        printWindow.document.write(html);
        printWindow.document.close();
        printWindow.focus();
        printWindow.print();
    };

    const handleMouseEnter = (talent) => {
        setHoveredTalentId(talent.id);
    };

    const handleMouseLeave = () => {
        setHoveredTalentId(null);
    };

    // Analyze the tree's coordinate system so every node can be placed without
    // ever overlapping its neighbours, regardless of viewport width.
    const treeAnalysis = React.useMemo(() => {
        const talentsList = currentTree?.talents || [];

        const usesIdTiers = talentsList.some(t => t.id && /_t[1-7]_/i.test(t.id));
        const tierMap = {};
        const tierGates = {};

        if (!talentsList.length) {
            for (let tier = 1; tier <= 7; tier++) {
                tierMap[tier] = tier - 1;
                tierGates[tier] = getRequiredPointsForTier(tier);
            }
            return { columns: [], minX: 0, maxX: 4, minGap: 1, maxTreeY: 6, tierMap, tierGates, tierCount: 7 };
        }

        const xs = talentsList.map(t => t.position?.x ?? 0);
        const ys = talentsList.map(t => t.position?.y ?? 0);
        const minX = Math.min(...xs);
        const maxX = Math.max(...xs);
        const maxTreeY = Math.max(...ys, 6);

        const columns = Array.from(new Set(xs)).sort((a, b) => a - b);

        // Nodes can only collide with neighbours on the same row: tier rows are
        // at least 76px tall while nodes cap at 64px, so different rows always
        // clear each other vertically. Measure the tightest same-row column
        // pair instead of the global column set (which would over-constrain
        // rows that share no y).
        const byRow = new Map();
        talentsList.forEach(t => {
            const y = t.position?.y ?? 0;
            if (!byRow.has(y)) byRow.set(y, []);
            byRow.get(y).push(t.position?.x ?? 0);
        });
        let minGap = Infinity;
        byRow.forEach(rowXs => {
            const rowColumns = Array.from(new Set(rowXs)).sort((a, b) => a - b);
            for (let i = 1; i < rowColumns.length; i++) {
                minGap = Math.min(minGap, rowColumns[i] - rowColumns[i - 1]);
            }
        });
        if (!isFinite(minGap) || minGap <= 0) minGap = 1;

        let tierCount;
        if (usesIdTiers) {
            tierCount = 7;
            for (let tier = 1; tier <= 7; tier++) {
                tierMap[tier] = tier - 1;
                tierGates[tier] = getRequiredPointsForTier(tier);
                const tierTalents = talentsList.filter(t => t.id && t.id.toLowerCase().includes(`_t${tier}_`));
                if (tierTalents.length > 0) {
                    tierMap[tier] = tierTalents[0].position?.y ?? (tier - 1);
                }
            }
        } else {
            const rows = Array.from(new Set(ys)).sort((a, b) => a - b);
            tierCount = Math.max(1, rows.length);
            rows.forEach((y, index) => {
                const rowNodes = talentsList.filter(t => (t.position?.y ?? 0) === y);
                const explicitGates = rowNodes.map(t => t.requiresPoints).filter(v => Number.isFinite(v));
                tierMap[index + 1] = y;
                tierGates[index + 1] = explicitGates.length
                    ? Math.max(...explicitGates)
                    : index * (TALENT_SYSTEM?.POINTS_PER_TIER_GATE || 5);
            });
        }

        return { columns, minX, maxX, minGap, maxTreeY, tierMap, tierGates, tierCount };
    }, [currentTree]);

    const cellHeight = Math.max(76, Math.floor(gridDims.height / 7));
    const boardHeight = Math.ceil((treeAnalysis.maxTreeY + 1.2) * cellHeight);

    // Preferred node size: readable, but never taller than a tier row.
    const desiredNodeSize = Math.max(
        MIN_NODE_SIZE,
        Math.min(64, gridDims.width * 0.16, cellHeight * 0.74)
    );

    // The board must always fit the viewport width so the tree never needs
    // horizontal panning. Side margins reserve room for the arrow SVGs (which
    // overhang their endpoints by ~20px) and keep nodes clear of the edge.
    const sideMarginFor = (nodeSize) => Math.max(nodeSize / 2 + 22, 26);
    const xRange = treeAnalysis.maxX - treeAnalysis.minX;
    const availableContentWidth = Math.min(gridDims.width, MAX_BOARD_WIDTH);

    // Pass 1: estimate the node size the tightest column pair can hold at the
    // preferred readability, shrinking nodes (never widening the board) when
    // the tree packs columns closer than the preferred size allows.
    const preferredSideMargin = sideMarginFor(desiredNodeSize);
    const preferredScale = xRange > 0
        ? (availableContentWidth - preferredSideMargin * 2) / xRange
        : 0;
    const preferredSlot = treeAnalysis.minGap * preferredScale;
    const preferredGap = Math.max(4, Math.min(NODE_GAP, preferredSlot * 0.25));
    const talentSize = treeAnalysis.columns.length > 1
        ? Math.min(desiredNodeSize, Math.max(12, preferredSlot - preferredGap))
        : desiredNodeSize;

    // Pass 2: re-fit with the final node size so columns spread edge to edge
    // across the available width and the tree stays centred.
    const sideMargin = sideMarginFor(talentSize);
    const usableWidth = Math.max(availableContentWidth - sideMargin * 2, 1);
    const xScale = xRange > 0 ? usableWidth / xRange : 0.0001;
    const contentWidth = availableContentWidth;

    const getNodePos = useCallback((x, y) => {
        const posY = y * cellHeight + cellHeight / 2;
        if (xRange <= 0) {
            return { posX: contentWidth / 2, posY };
        }
        const posX = sideMargin + (x - treeAnalysis.minX) * xScale;
        return { posX, posY };
    }, [treeAnalysis, cellHeight, contentWidth, sideMargin, xScale, xRange]);

    if (!trees || trees.length === 0) {
        return (
            <div className="talent-tree-content-root">
                <div className="talent-tree-empty-state">
                    <h2>No Talent Trees Found</h2>
                    <p>Select a valid character class to view talent trees.</p>
                </div>
            </div>
        );
    }

    // Determine inspector talent
    const inspectedTalent = currentTree?.talents?.find(t => t.id === (selectedTalentId || hoveredTalentId))
        || currentTree?.talents?.[0];
    const selectedTalent = selectedTalentId
        ? currentTree?.talents?.find(t => t.id === selectedTalentId) || null
        : null;
    const inspectedRanks = inspectedTalent ? (talents[inspectedTalent.id] || 0) : 0;
    const inspectedMaxed = inspectedTalent ? (inspectedRanks >= (inspectedTalent.maxRanks || 1)) : false;
    const inspectedCanLearn = inspectedTalent ? canLearnTalent(inspectedTalent) : false;
    const inspectedCanUnlearn = inspectedTalent ? canUnlearnTalent(inspectedTalent.id) : false;

    const spentInActiveTree = currentTree?.talents?.reduce((sum, t) => sum + (talents[t.id] || 0), 0) || 0;

    return (
        <div className="talent-tree-content-root">
            {!hideHeader && (
                <div className="talent-tree-top-bar">
                    <div className="talent-tree-header-left">
                        {activeTree < trees.length ? (
                            <div className="talent-active-spec-header">
                                <div className="talent-spec-header-crest">
                                    <img
                                        src={getIconUrl(currentTree?.icon || 'Utility/Utility', 'abilities')}
                                        alt=""
                                        className="talent-spec-header-icon"
                                        onError={(e) => { e.target.src = getIconUrl('Utility/Utility', 'abilities'); }}
                                    />
                                </div>
                                <div className="talent-spec-header-info">
                                    <div className="talent-spec-header-top-row">
                                        <h3 className="talent-spec-header-title">{currentTree?.name}</h3>
                                        <span className="talent-spec-class-tag">{characterClass} Specialization</span>
                                        {readOnly ? (
                                            <span className="talent-spec-invested-pill codex-pill">
                                                <i className="fas fa-sitemap"></i> 50 Capacity • 7 Tiers
                                            </span>
                                        ) : (
                                            <>
                                                <span className="talent-spec-invested-pill">
                                                    <i className="fas fa-sparkles"></i> {spentInActiveTree} Pts Allocated
                                                </span>
                                                {primarySpecialization === currentTree?.id && spentInActiveTree > 0 && (
                                                    <span className="talent-primary-spec-badge" title="Active Primary Specialization — granted from investing your first talent point">
                                                        <i className="fas fa-crown"></i> Primary Specialization
                                                    </span>
                                                )}
                                            </>
                                        )}
                                    </div>
                                    <div className="talent-spec-header-desc" title={currentTree?.description}>
                                        "{currentTree?.description}"
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="talent-active-spec-header">
                                <div className="talent-spec-header-crest summary-crest">
                                    <i className="fas fa-book-bookmark"></i>
                                </div>
                                <div className="talent-spec-header-info">
                                    <div className="talent-spec-header-top-row">
                                        <h3 className="talent-spec-header-title">Mastery Grimoire</h3>
                                        <span className="talent-spec-class-tag">{characterClass} Compendium</span>
                                        <span className="talent-spec-invested-pill summary-pill">
                                            <i className="fas fa-layer-group"></i> {readOnly ? 'Full Ability Catalog' : `${pointsSpent} Total Points`}
                                        </span>
                                    </div>
                                    <div className="talent-spec-header-desc">
                                        Complete compendium of all learned abilities, techniques, and stances across {characterClass} specializations.
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="talent-stats-bar">
                        {readOnly ? (
                            <div className="talent-points-badge codex-badge">
                                <i className="fas fa-book-open"></i>
                                <span>Tradition Codex Mode</span>
                            </div>
                        ) : (
                            <>
                                <div className="talent-points-badge">
                                    <span>Talent Points:</span>
                                    <span className="points-val">{pointsSpent}</span>
                                    <span>/</span>
                                    <span className="points-avail">{availablePoints}</span>
                                    <span className="points-remaining-tag">({pointsRemaining} Left)</span>
                                </div>
                                <button type="button" className="talent-reset-btn" onClick={resetTalents} title="Refund all talent points in this character">
                                    Reset All
                                </button>
                            </>
                        )}
                        <button
                            type="button"
                            className={`talent-help-btn${helpOpen ? ' active' : ''}`}
                            onClick={toggleHelp}
                            aria-expanded={helpOpen}
                            aria-label="How talents work"
                            title="How talents work"
                        >
                            <i className="fas fa-question"></i>
                            <span>How Talents Work</span>
                        </button>
                    </div>
                </div>
            )}

            {helpOpen && (
                <div className="talent-help-panel" role="note">
                    <div className="talent-help-row">
                        <span className="talent-help-chip"><i className="fas fa-star"></i> 5 points per level · 50 total</span>
                        <span className="talent-help-chip"><i className="fas fa-sitemap"></i> Max one tree, or split across trees (capstones need 30 in-tree)</span>
                        <span className="talent-help-chip"><i className="fas fa-lock"></i> Tier T# unlocks after 5 × (T# − 1) points in that tree</span>
                    </div>
                    <div className="talent-help-row talent-help-legend">
                        <span className="talent-help-legend-item"><i className="talent-help-swatch swatch-available"></i> Available</span>
                        <span className="talent-help-legend-item"><i className="talent-help-swatch swatch-learned"></i> Learned</span>
                        <span className="talent-help-legend-item"><i className="talent-help-swatch swatch-maxed"></i> Maxed</span>
                        <span className="talent-help-legend-item"><i className="talent-help-swatch swatch-locked"></i> Locked</span>
                        <span className="talent-help-legend-item"><i className="fas fa-arrow-right"></i> Prerequisite</span>
                        {!readOnly && (
                            <span className="talent-help-legend-item">
                                <i className={isTouchLayout ? 'fas fa-hand-pointer' : 'fas fa-mouse-pointer'}></i>
                                {isTouchLayout ? 'Tap a node to inspect, then Learn / Refund below' : 'Click to learn · Right-click to refund'}
                            </span>
                        )}
                    </div>
                </div>
            )}

            {activeTree === trees.length ? (
                <div className="talent-summary-view-wrapper">
                    <div className="talent-summary-scroll-content">
                        <div className="talent-summary-heading-box">
                            <i className="fas fa-scroll"></i>
                            <h3>Chronicled Talents & Masteries</h3>
                            <p>{readOnly ? 'Complete reference of abilities and innate passive traits across all specializations.' : 'Herein lies the complete record of abilities and innate specialization passives unlocked through your progression.'}</p>
                            {!readOnly && (
                                <div className="talent-summary-actions">
                                    <button type="button" className="talent-table-btn" onClick={handleCopyBuild}>
                                        <i className="fas fa-copy"></i>
                                        <span>{copyState === 'copied' ? 'Copied!' : 'Copy Build Text'}</span>
                                    </button>
                                    <button type="button" className="talent-table-btn" onClick={handlePrintBuild}>
                                        <i className="fas fa-print"></i>
                                        <span>Print Build Sheet</span>
                                    </button>
                                </div>
                            )}
                        </div>

                        {trees.map((tree, tIdx) => {
                            const displayTalents = readOnly ? (tree.talents || []) : (tree.talents || []).filter(t => (talents[t.id] || 0) > 0);
                            const treePoints = (tree.talents || []).reduce((sum, t) => sum + (talents[t.id] || 0), 0);
                            const isPrimaryTree = primarySpecialization === tree.id || (treePoints > 0 && (!primarySpecialization || primarySpecialization === tree.id));

                            return (
                                <div key={tree.id || tIdx} className={`talent-summary-tree-section ${isPrimaryTree && treePoints > 0 ? 'is-primary-spec-section' : ''}`}>
                                    <div className="talent-summary-tree-header">
                                        <div className="summary-tree-title-group">
                                            <img
                                                src={getIconUrl(tree.icon, 'abilities')}
                                                alt={tree.name}
                                                className="talent-summary-tree-icon"
                                                onError={(e) => { e.target.src = getIconUrl('Utility/Utility', 'abilities'); }}
                                            />
                                            <h4>{tree.name}</h4>
                                            {isPrimaryTree && treePoints > 0 && (
                                                <span className="summary-primary-badge">
                                                    <i className="fas fa-crown"></i> Primary Specialization
                                                </span>
                                            )}
                                        </div>
                                        <span className={`talent-summary-count-tag ${displayTalents.length > 0 ? 'has-learned' : ''}`}>
                                            {readOnly ? `${displayTalents.length} Total Talents` : `${displayTalents.length} Talents Learned (${treePoints} Pts)`}
                                        </span>
                                    </div>

                                    {/* Innate Passive Traits for this Specialization - ONLY displayed for the Active Primary Specialization */}
                                    {tree.passives && tree.passives.length > 0 && (readOnly || (isPrimaryTree && treePoints > 0)) && (
                                        <div className="talent-summary-passives-section active-passives">
                                            <div className="summary-passives-header-row">
                                                <div className="summary-passives-label">
                                                    <i className="fas fa-shield-halved"></i>
                                                    <span>Active Innate Passive Traits:</span>
                                                </div>
                                                {!readOnly && (
                                                    <span className="summary-passives-status active">
                                                        <i className="fas fa-check-circle"></i> Specialization Passives Active
                                                    </span>
                                                )}
                                            </div>
                                            <div className="summary-passives-cards-grid">
                                                {tree.passives.map((p, pIdx) => (
                                                    <div key={pIdx} className={`summary-passive-card ${p.isShared ? 'shared-trait' : 'unique-trait'}`}>
                                                        <div className="summary-passive-card-top">
                                                            <span className="summary-passive-tier-badge">{p.tier || 'Passive'}</span>
                                                            <strong className="summary-passive-title">{p.name}</strong>
                                                        </div>
                                                        <p className="summary-passive-desc">{p.description}</p>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {displayTalents.length === 0 ? (
                                        <div className="talent-summary-empty-msg">
                                            No talent points invested in this specialization yet.
                                        </div>
                                    ) : (
                                        <div className="talent-summary-items-list">
                                            {displayTalents.map(talent => {
                                                const curRanks = readOnly ? (talent.maxRanks || 1) : (talents[talent.id] || 0);
                                                const isMaxed = curRanks >= (talent.maxRanks || 1);
                                                const talentTier = getNodeTier(talent);

                                                return (
                                                    <div key={talent.id} className={`talent-summary-item-card ${isMaxed ? 'is-maxed' : 'is-learned'}`}>
                                                        <div className="talent-summary-card-left">
                                                            <div className="talent-summary-icon-frame">
                                                                <img
                                                                    src={getIconUrl(talent.icon, 'abilities')}
                                                                    alt={talent.name}
                                                                    className="talent-summary-item-img"
                                                                    onError={(e) => { e.target.src = getIconUrl('Utility/Utility', 'abilities'); }}
                                                                />
                                                            </div>
                                                        </div>
                                                        <div className="talent-summary-item-info">
                                                            <div className="talent-summary-card-header">
                                                                <div className="talent-summary-title-group">
                                                                    <h5 className="talent-summary-item-name">{talent.name}</h5>
                                                                    <span className={`talent-summary-rank-badge ${isMaxed ? 'maxed' : 'learned'}`}>
                                                                        {readOnly
                                                                            ? `${talent.maxRanks || 1} Rank${(talent.maxRanks || 1) > 1 ? 's' : ''}`
                                                                            : `Rank ${curRanks} of ${talent.maxRanks || 1}${isMaxed ? ' (Maxed)' : ''}`
                                                                        }
                                                                    </span>
                                                                    <span className="talent-summary-tier-tag">Tier {talentTier}</span>
                                                                </div>
                                                                <div className="talent-summary-item-meta">
                                                                    {renderSpellMetaChips(talent.spell)}
                                                                </div>
                                                            </div>
                                                            <div className="talent-summary-item-desc">
                                                                {getDynamicDescription(talent, curRanks, readOnly)}
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            ) : (
                <div className="talent-split-book-layout">
                    <div className="talent-tree-page-canvas">
                        <div
                            className="talent-backdrop-layer"
                            style={{
                                backgroundImage: currentTree?.backdrop || currentTree?.fallbackBackground
                            }}
                        />

                        <div className="talent-tree-scroll-container">
                            <div className="talent-tier-rail" style={{ height: `${boardHeight}px` }}>
                                {Array.from({ length: treeAnalysis.tierCount || 7 }, (_, i) => i + 1).map(tier => {
                                    const tierY = treeAnalysis.tierMap[tier] ?? (tier - 1);
                                    const { posY } = getNodePos(0, tierY);
                                    const reqPoints = treeAnalysis.tierGates?.[tier] ?? getRequiredPointsForTier(tier);
                                    const isTierLocked = treePointsSpent < reqPoints;

                                    return (
                                        <div
                                            key={tier}
                                            className={`talent-tier-label ${isTierLocked ? 'locked' : 'unlocked'}`}
                                            style={{
                                                position: 'absolute',
                                                top: `${posY}px`,
                                                transform: 'translateY(-50%)'
                                            }}
                                            title={`Tier ${tier}: Requires ${reqPoints} points spent in ${currentTree?.name || 'this tree'}`}
                                        >
                                            <span className="tier-name">T{tier}</span>
                                            <span className="tier-pts">{reqPoints}p</span>
                                            {isTierLocked && <i className="fas fa-lock tier-lock-icon"></i>}
                                        </div>
                                    );
                                })}
                            </div>

                            <div
                                ref={boardRef}
                                className="talent-grid-board"
                                style={{
                                    height: `${boardHeight}px`,
                                    minHeight: `${boardHeight}px`,
                                    width: `${contentWidth}px`,
                                    maxWidth: 'none',
                                    margin: '0 auto'
                                }}
                            >
                                <TalentArrowRenderer
                                    talents={currentTree?.talents || []}
                                    learnedTalents={talents}
                                    cellWidth={contentWidth / 5}
                                    cellHeight={cellHeight}
                                    talentSize={talentSize}
                                    getNodePos={getNodePos}
                                />

                                {(currentTree?.talents || []).map(talent => {
                                    const curRanks = talents[talent.id] || 0;
                                    const isMaxed = curRanks >= (talent.maxRanks || 1);
                                    const canLearn = canLearnTalent(talent);
                                    const isLearnable = canLearn && !isMaxed;
                                    const isLocked = isNodeLocked(talent);
                                    const isSelected = inspectedTalent?.id === talent.id;

                                    const tierReqPoints = getNodePointGate(talent);
                                    const levelLocked = Number.isFinite(talent.minLevel) && level < talent.minLevel;
                                    const lockedTitle = levelLocked
                                        ? `${talent.name} — locked: requires character level ${talent.minLevel}`
                                        : treePointsSpent < tierReqPoints
                                            ? `${talent.name} — locked: requires ${tierReqPoints} points spent in ${currentTree?.name || 'this tree'}`
                                            : `${talent.name} — locked: complete its prerequisites first`;

                                    const { posX, posY } = getNodePos(talent.position?.x ?? 0, talent.position?.y ?? 0);

                                    return (
                                        <div
                                            key={talent.id}
                                            className="talent-node-cell"
                                            style={{
                                                left: `${posX}px`,
                                                top: `${posY}px`,
                                                transform: 'translate(-50%, -50%)',
                                                width: `${talentSize}px`,
                                                height: `${talentSize}px`
                                            }}
                                        >
                                            <button
                                                type="button"
                                                className={`talent-node-btn talent-node-button ${curRanks > 0 ? 'learned' : ''} ${isMaxed ? 'maxed' : ''} ${isLearnable ? 'learnable' : ''} ${isLocked ? 'locked' : ''} ${isSelected ? 'selected' : ''}`}
                                                title={isLocked ? lockedTitle : `${talent.name} (${curRanks}/${talent.maxRanks || 1})`}
                                                onClick={() => {
                                                    setSelectedTalentId(talent.id);
                                                    if (!readOnly && !isTouchLayout) {
                                                        handleTalentClick(talent.id, talent);
                                                    }
                                                }}
                                                onContextMenu={(e) => {
                                                    if (!readOnly) {
                                                        handleTalentRightClick(e, talent.id, talent);
                                                    }
                                                }}
                                                onMouseEnter={() => setHoveredTalentId(talent.id)}
                                                onMouseLeave={() => setHoveredTalentId(null)}
                                            >
                                                <span className="talent-node-icon-box">
                                                    <img
                                                        src={getIconUrl(talent.icon, 'abilities')}
                                                        alt={talent.name}
                                                        className="talent-node-img"
                                                        onError={(e) => { e.target.src = getIconUrl('Utility/Utility', 'abilities'); }}
                                                    />
                                                </span>

                                                <span className={`talent-node-rank-badge ${isMaxed ? 'maxed' : curRanks > 0 ? 'learned' : ''}`}>
                                                    {readOnly ? (talent.maxRanks || 1) : `${curRanks}/${talent.maxRanks || 1}`}
                                                </span>
                                            </button>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>

                    <div className="talent-inspector-page">
                        {inspectedTalent ? (() => {
                            const inspectedTier = getNodeTier(inspectedTalent);
                            const inspectedReqTierPoints = getNodePointGate(inspectedTalent);
                            const isTierMet = treePointsSpent >= inspectedReqTierPoints;
                            const isLevelMet = !Number.isFinite(inspectedTalent.minLevel) || level >= inspectedTalent.minLevel;
                            const unlearnCheck = canUnlearnTalent(inspectedTalent.id);
                            const inspectedCanUnlearn = unlearnCheck.canUnlearn;

                            return (
                            <div className="talent-inspector-card">
                                <div className="talent-inspector-header">
                                    <img
                                        src={getIconUrl(inspectedTalent.icon, 'abilities')}
                                        alt={inspectedTalent.name}
                                        className="talent-inspector-icon"
                                        onError={(e) => { e.target.src = getIconUrl('Utility/Utility', 'abilities'); }}
                                    />
                                    <div className="talent-inspector-title-block">
                                        <h4>{inspectedTalent.name}</h4>
                                        <div className="talent-inspector-rank-row">
                                            {readOnly ? (
                                                <span className="talent-inspector-rank-tag codex-rank-tag">
                                                    {inspectedTalent.maxRanks || 1} Rank{(inspectedTalent.maxRanks || 1) > 1 ? 's' : ''} Max
                                                </span>
                                            ) : (
                                                <span className={`talent-inspector-rank-tag ${inspectedMaxed ? 'maxed' : inspectedRanks > 0 ? 'learned' : 'unlearned'}`}>
                                                    Rank {inspectedRanks} of {inspectedTalent.maxRanks || 1} {inspectedMaxed ? '(Maxed)' : inspectedCanLearn ? '(Learnable)' : ''}
                                                </span>
                                            )}
                                            <span className="talent-tier-pos-tag">Tier {inspectedTier}</span>
                                        </div>
                                    </div>
                                </div>

                                <div className="talent-inspector-meta-box">
                                    {renderSpellMetaChips(inspectedTalent.spell)}
                                </div>

                                <div className="talent-inspector-body">
                                    <div className="talent-inspector-desc-scroll">
                                        {getDynamicDescription(inspectedTalent, inspectedRanks, readOnly)}
                                    </div>

                                    {/* Requirements status */}
                                    {(inspectedReqTierPoints > 0 || inspectedTalent.requires || Number.isFinite(inspectedTalent.minLevel)) && (
                                        <div className="talent-inspector-reqs-box">
                                            <span className="req-box-title">Requirements:</span>
                                            {inspectedReqTierPoints > 0 && (
                                                <div className={`req-item-line ${readOnly ? 'met' : isTierMet ? 'met' : 'unmet'}`}>
                                                    <i className={`fas ${readOnly || isTierMet ? 'fa-check-circle' : 'fa-lock'}`}></i>
                                                    <span>Requires {inspectedReqTierPoints} points spent in {currentTree?.name || 'this tree'}</span>
                                                </div>
                                            )}
                                            {Number.isFinite(inspectedTalent.minLevel) && (
                                                <div className={`req-item-line ${readOnly || isLevelMet ? 'met' : 'unmet'}`}>
                                                    <i className={`fas ${readOnly || isLevelMet ? 'fa-check-circle' : 'fa-lock'}`}></i>
                                                    <span>Requires character level {inspectedTalent.minLevel}</span>
                                                </div>
                                            )}
                                            {inspectedTalent.requires && (() => {
                                                const reqIds = Array.isArray(inspectedTalent.requires) ? inspectedTalent.requires : [inspectedTalent.requires];
                                                return reqIds.map(reqId => {
                                                    const reqNode = currentTree?.talents?.find(t => t.id === reqId);
                                                    const reqName = reqNode ? reqNode.name : 'Prerequisite Talent';
                                                    const reqRanks = reqNode?.maxRanks || 1;
                                                    const curReqRanks = talents[reqId] || 0;
                                                    const isMet = curReqRanks >= reqRanks;

                                                    return (
                                                        <div key={reqId} className={`req-item-line ${readOnly || isMet ? 'met' : 'unmet'}`}>
                                                            <i className={`fas ${readOnly || isMet ? 'fa-check-circle' : 'fa-lock'}`}></i>
                                                            <span>Prerequisite: {reqName} ({reqRanks} rank{reqRanks > 1 ? 's' : ''})</span>
                                                        </div>
                                                    );
                                                });
                                            })()}
                                        </div>
                                    )}

                                </div>

                                {/* Direct Allocation Action Buttons */}
                                {readOnly ? (
                                    <div className="talent-inspector-actions codex-actions">
                                        <div className="talent-codex-hint">
                                            <i className="fas fa-eye"></i>
                                            <span>Click nodes to view full rank progressions and mechanics.</span>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="talent-inspector-actions">
                                        <button
                                            type="button"
                                            className="talent-action-btn learn-btn"
                                            disabled={inspectedMaxed || !inspectedCanLearn}
                                            onClick={() => handleTalentClick(inspectedTalent.id, inspectedTalent)}
                                        >
                                            <i className="fas fa-plus-circle"></i>
                                            <span>Learn Rank (+1)</span>
                                        </button>
                                        <button
                                            type="button"
                                            className="talent-action-btn refund-btn"
                                            disabled={inspectedRanks <= 0 || !inspectedCanUnlearn}
                                            onClick={(e) => handleTalentRightClick(e, inspectedTalent.id, inspectedTalent)}
                                        >
                                            <i className="fas fa-rotate-left"></i>
                                            <span>Refund (-1)</span>
                                        </button>
                                    </div>
                                )}
                            </div>
                            );
                        })() : (
                            <div className="talent-inspector-empty">
                                <i className="fas fa-scroll"></i>
                                <h4>{currentTree?.name || 'Specialization Codex'}</h4>
                                <p>{currentTree?.description}</p>
                                {currentTree?.passives && currentTree.passives.length > 0 && (
                                    <div className="inspector-empty-passives">
                                        <div className="empty-passives-title">
                                            <i className="fas fa-shield-halved"></i> Innate Passive Traits
                                        </div>
                                        {currentTree.passives.map((p, idx) => (
                                            <div key={idx} className={`inspector-passive-item ${p.isShared ? 'shared' : 'unique'}`}>
                                                <div className="inspector-passive-header">
                                                    <strong>{p.name}</strong>
                                                    <span className="inspector-passive-tier">{p.tier || 'Passive'}</span>
                                                </div>
                                                <p className="inspector-passive-desc">{p.description}</p>
                                            </div>
                                        ))}
                                    </div>
                                )}
                                <span>Click any talent node on the left to examine its scaling powers and assign points.</span>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Touch allocation bar: inspect first, then allocate deliberately */}
            {!readOnly && isTouchLayout && activeTree !== trees.length && selectedTalent && (() => {
                const rank = talents[selectedTalent.id] || 0;
                const maxRank = selectedTalent.maxRanks || 1;
                const maxed = rank >= maxRank;
                const canLearn = canLearnTalent(selectedTalent);
                const unlearnCheck = canUnlearnTalent(selectedTalent.id);
                const status = maxed ? 'Maxed' : canLearn ? 'Learnable' : isNodeLocked(selectedTalent) ? 'Locked' : '';

                return (
                    <div className="talent-touch-bar" role="toolbar" aria-label="Selected talent actions">
                        <button
                            type="button"
                            className="talent-touch-bar__info"
                            onClick={() => {
                                const inspector = document.querySelector('.talent-inspector-page');
                                inspector?.scrollIntoView({ behavior: 'smooth', block: 'start' });
                            }}
                            title="View full details"
                        >
                            <img
                                src={getIconUrl(selectedTalent.icon, 'abilities')}
                                alt=""
                                className="talent-touch-bar__thumb"
                                onError={(e) => { e.target.src = getIconUrl('Utility/Utility', 'abilities'); }}
                            />
                            <span className="talent-touch-bar__text">
                                <span className="talent-touch-bar__name">{selectedTalent.name}</span>
                                <span className="talent-touch-bar__sub">
                                    Rank {rank} of {maxRank} · Tier {getNodeTier(selectedTalent)}
                                    {status ? ` · ${status}` : ''}
                                </span>
                            </span>
                        </button>
                        <div className="talent-touch-bar__actions">
                            <button
                                type="button"
                                className="talent-action-btn refund-btn"
                                disabled={rank <= 0 || !unlearnCheck.canUnlearn}
                                onClick={(e) => handleTalentRightClick(e, selectedTalent.id, selectedTalent)}
                                title="Refund one rank"
                            >
                                <i className="fas fa-rotate-left"></i>
                                <span>−1</span>
                            </button>
                            <button
                                type="button"
                                className="talent-action-btn learn-btn"
                                disabled={maxed || !canLearn}
                                onClick={() => handleTalentClick(selectedTalent.id, selectedTalent)}
                                title="Learn one rank"
                            >
                                <i className="fas fa-plus-circle"></i>
                                <span>+1</span>
                            </button>
                        </div>
                    </div>
                );
            })()}

            {/* Error Popup */}
            {unlearnError && (
                <div
                    style={{
                        position: 'fixed',
                        left: unlearnError.position.x + 12,
                        top: unlearnError.position.y - 12,
                        background: '#8b0000',
                        color: '#fff',
                        padding: '8px 14px',
                        borderRadius: '6px',
                        fontSize: '0.85rem',
                        fontWeight: 'bold',
                        boxShadow: '0 4px 14px rgba(0,0,0,0.6)',
                        zIndex: 99999,
                        pointerEvents: 'none'
                    }}
                >
                    {unlearnError.message}
                </div>
            )}
        </div>
    );
};

export default TalentTreeContent;

import React from 'react';
import { render, screen, fireEvent, within, waitFor } from '@testing-library/react';
import { TalentTreeContent, buildBuildText, getTalentTreesForClass } from '../TalentTreeContent';
import useCharacterStore from '../../../store/characterStore';
import useSpellbookStore from '../../../store/spellbookStore';
import { convertTalentSpellToLibrarySpell } from '../../../data/talentTrees/talentSystem.mjs';
import { GAMBIT_PROBABILITY_SAVANT, GAMBIT_HIGH_ROLLER, GAMBIT_KARMIC_WEAVER } from '../../../data/talentTrees/gambit.js';

describe('Talent Tree System Tests', () => {
  const originalMatchMedia = window.matchMedia;

  beforeEach(() => {
    window.localStorage.clear();
    useCharacterStore.setState({
      class: 'Gambit',
      level: 2,
      currentCharacterId: 'char-123',
      talents: {}
    });
    useSpellbookStore.setState({
      spells: []
    });
  });

  afterEach(() => {
    window.matchMedia = originalMatchMedia;
  });

  test('renders active talent tree header and points badge', () => {
    render(<TalentTreeContent />);
    expect(screen.getByText('Probability Savant')).toBeInTheDocument();
    expect(screen.getByText('Talent Points:')).toBeInTheDocument();
    expect(screen.getByText('Reset All')).toBeInTheDocument();
  });

  test('renders talent summary view when selectedTreeIndex is summary', () => {
    render(<TalentTreeContent selectedTreeIndex={3} />);
    expect(screen.getByText('Mastery Grimoire')).toBeInTheDocument();
    expect(screen.getByText('Chronicled Talents & Masteries')).toBeInTheDocument();
  });

  test('convertTalentSpellToLibrarySpell generates accurate spell library object with resources and AP', () => {
    const talentNode = GAMBIT_PROBABILITY_SAVANT.find(t => t.id === 'ps_t1_calculated_nudge');
    expect(talentNode).toBeDefined();

    const librarySpell = convertTalentSpellToLibrarySpell(talentNode, 1);
    expect(librarySpell).toBeDefined();
    expect(librarySpell.id).toBe('talent-spell-ps_t1_calculated_nudge');
    expect(librarySpell.source).toBe('talent');
    expect(librarySpell.spellType).toBe('REACTION');
    expect(librarySpell.actionType).toBe('reaction');
    expect(librarySpell.reactionTrigger).toBeTruthy();
    expect(librarySpell.resourceCost.actionPoints).toBe(0);
    expect(librarySpell.resourceCost.resourceValues.fortunePoints).toBe(1);
    expect(librarySpell.cooldownConfig.cooldownValue).toBe(1);
  });

  test('Gambit talents across all 3 specs have zero percentage values in descriptions', () => {
    [...GAMBIT_PROBABILITY_SAVANT, ...GAMBIT_HIGH_ROLLER, ...GAMBIT_KARMIC_WEAVER].forEach(node => {
      expect(node.spell.description).not.toMatch(/%/);
      if (node.rankUpgrades) {
        node.rankUpgrades.forEach(upgrade => {
          if (upgrade.description) {
            expect(upgrade.description).not.toMatch(/%/);
          }
        });
      }
    });
  });

  test('clicking talent adds ranks and syncs spellbook', () => {
    const { container } = render(<TalentTreeContent />);
    const nodeButtons = container.querySelectorAll('.talent-node-button');
    expect(nodeButtons.length).toBeGreaterThan(0);

    // Click the first learnable talent node
    fireEvent.click(nodeButtons[0]);

    const state = useCharacterStore.getState();
    const learnedTalentKeys = Object.keys(state.talents);
    expect(learnedTalentKeys.length).toBe(1);
    expect(state.talents[learnedTalentKeys[0]]).toBe(1);

    // Verify spellbook has the learned spell
    const spells = useSpellbookStore.getState().spells;
    expect(spells.length).toBe(1);
    expect(spells[0].id).toBe(`talent-spell-${learnedTalentKeys[0]}`);
  });

  test('Reset All clears talents and removes talent spells from spellbook', () => {
    const { container } = render(<TalentTreeContent />);
    const nodeButtons = container.querySelectorAll('.talent-node-button');

    // Learn a talent
    fireEvent.click(nodeButtons[0]);
    expect(Object.keys(useCharacterStore.getState().talents).length).toBe(1);

    // Click reset all
    const resetBtn = screen.getByText('Reset All');
    fireEvent.click(resetBtn);

    expect(Object.keys(useCharacterStore.getState().talents).length).toBe(0);
    expect(useSpellbookStore.getState().spells.length).toBe(0);
  });

  test('5-point tier gatekeeping: Tier 2 requires 5 points spent in tree', () => {
    const { getNodeTier, getRequiredPointsForTier } = require('../TalentTreeContent');
    expect(getRequiredPointsForTier(1)).toBe(0);
    expect(getRequiredPointsForTier(2)).toBe(5);
    expect(getRequiredPointsForTier(3)).toBe(10);
    expect(getRequiredPointsForTier(4)).toBe(15);
    expect(getRequiredPointsForTier(5)).toBe(20);
    expect(getRequiredPointsForTier(6)).toBe(25);
    expect(getRequiredPointsForTier(7)).toBe(30);

    const t1Node = GAMBIT_PROBABILITY_SAVANT.find(t => t.id.includes('_t1_'));
    const t2Node = GAMBIT_PROBABILITY_SAVANT.find(t => t.id.includes('_t2_'));
    const t3Node = GAMBIT_PROBABILITY_SAVANT.find(t => t.id.includes('_t3_'));
    expect(getNodeTier(t1Node)).toBe(1);
    expect(getNodeTier(t2Node)).toBe(2);
    expect(getNodeTier(t3Node)).toBe(3);
  });

  test('cannot allocate Tier 2 talent with less than 5 points in tree', () => {
    useCharacterStore.setState({
      class: 'Gambit',
      level: 10,
      talents: {
        'ps_t1_calculated_nudge': 3 // 3 points in Tier 1 (< 5 needed for Tier 2)
      }
    });

    const { container } = render(<TalentTreeContent />);

    // Find all rendered nodes
    const nodeButtons = container.querySelectorAll('.talent-node-button');
    expect(nodeButtons.length).toBeGreaterThan(0);

    // Tier 2 nodes should be locked
    const t2Nodes = GAMBIT_PROBABILITY_SAVANT.filter(t => t.id.includes('_t2_'));
    expect(t2Nodes.length).toBeGreaterThan(0);

    // Click a Tier 2 node button
    // Should NOT increase ranks because tree points = 3 < 5
    const initialTalents = { ...useCharacterStore.getState().talents };
    const t2NodeElement = container.querySelector(`[data-talent-id="${t2Nodes[0].id}"]`) || nodeButtons[3];
    fireEvent.click(t2NodeElement);

    const state = useCharacterStore.getState();
    expect(state.talents[t2Nodes[0].id] || 0).toBe(0);
  });

  test('Tier 2 node can be learned once 5 points are invested in Tier 1', () => {
    // Invest 5 points across Tier 1 nodes
